    const LYRIC_EMPTY_GRACE_MS = 3600000;

    // localStorage key for songs made by trimming in the player, which the
    // list marks with a small T on their badge
    const TRIMMED_KEY = "mureka_trimmed_v1";

    // localStorage key for songs marked ignored, which a queue made from
    // the list leaves out. Played when asked for by name all the same
    const IGNORED_KEY = "mureka_ignored_v1";

    // localStorage key for song tweaks the user took away again, a rating,
    // a hand entered tempo or an instrumental mark, with when it happened.
    // Exported with the song tweaks, so an import can tell a value that was
    // removed on purpose from one that was never set
    const CLEARED_KEY = "mureka_cleared_v1";

    // localStorage key for tempos entered by hand. Mureka leaves bpm unset on
    // some songs, and without it they can only ever be excluded from a tempo
    // filter, so a value can be supplied and is then used like a real one
    const MANUAL_BPM_KEY = "mureka_manual_bpm_v1";

    // localStorage key for tempos worked out from the songs themselves,
    // {v, bpm: {song_id: [bpm, sureness, first found, moved, halfway,
    // halfway at double the period, how Mureka's tempo leaned it, halfway
    // in the deep band, thirds against halfway over two beats, the same in
    // the deep band, the way it was worked out, kick and snare taking
    // turns]}}, moved being 1 up, 2 up as kick and snare take turns, -1
    // down, 3 three beats where two were counted, 0 kept. One worked out an
    // older way is kept and used until the song comes up, or its Information
    // is opened, and is worked out again, so the BPM filter keeps it meanwhile. All are worked out again when
    // the way of working them out changes (v). A tempo is used only when
    // the beat stood out clearly enough (TEMPO_SURE, 0 to 1)
    const DETECTED_BPM_KEY = "mureka_detected_bpm_v1";
    const TEMPO_VERSION = 9;
    const TEMPO_SURE = 0.5;

    // localStorage key for star ratings, song_id to 0 to 5. A song missing
    // from it has never been rated, which is kept apart from zero stars
    const RATING_KEY = "mureka_rating_v1";

    // Star colors, lit and unlit. An unrated song shows grey outlines, a
    // rated one gold outlines, so zero stars and not rated look different
    const STAR_GOLD = "#f5c518";
    const STAR_EMPTY = "#6a6a74";

    // The outline of unlit stars on a rated song and of a partly lit star,
    // a dark gold so the lit ones stand out
    const STAR_DIM = "#7d6516";

    // Cache API bucket for the per song detail payload, the play and like
    // counts plus the timed lyrics. Counts change over time, so every entry
    // carries the moment it was stored and is refetched once it is too old
    const DETAIL_STORE = "mureka_detail_cache_v1";

    // Cache API bucket for the per song waveform. Only the feed responses carry
    // wave_list, so it is persisted here as feed pages arrive and read on play
    const WAVE_STORE = "mureka_wave_cache_v1";

    // Default number of upcoming songs to cache ahead, until a number is set
    // in the settings
    const PREFETCH_DEFAULT = 3;

    // Minutes since the last look for new songs before the player or a web
    // view in use looks again, when that is switched on. In steps of five
    // Play on after a quick restart: half a minute unless set, ten minutes at
    // the most
    const PLAY_ON_DEFAULT = 30;
    const PLAY_ON_MAX = 600;

    const REFRESH_RETURN_DEFAULT = 30;
    const REFRESH_RETURN_MAX = 1440;
    const REFRESH_RETURN_STEP = 5;

    // How often a player or web view in view sees whether it is time
    const REFRESH_RETURN_TICK_MS = 60000;

    // The values a copy can carry, in the order the copy box lists them
    const COPY_TYPES = [
        { key: "bpm", label: "Tempos (BPM)" },
        { key: "instr", label: "Instrumental marks" },
        { key: "rating", label: "Ratings" },
        { key: "ignore", label: "Ignored songs" },
        { key: "sets", label: "Song sets", only: "tweaks" }
    ];

    // What each kind of copy carries until chosen otherwise. Songs for
    // someone else leave the ratings and ignored songs out. Song sets only
    // go with song tweaks
    const COPY_DEFAULTS = {
        songs: { bpm: true, instr: true, rating: false, ignore: false, sets: false },
        queue: { bpm: true, instr: true, rating: false, ignore: false, sets: false },
        tweaks: { bpm: true, instr: true, rating: true, ignore: true, sets: true }
    };

    // The values a kind of copy can carry
    function copyTypesOf(kind) {

        return COPY_TYPES.filter(function (t) {
            return !t.only || t.only === kind;
        });
    }

    // Album art coverflow, the center cover takes this fraction of the width and
    // the previous and next covers peek in on the sides. Lower shows more of the
    // neighbors, 0.5 shows exactly half of each
    const ART_CENTER_FRACTION = 0.6;

    // Strongest blur on a side cover at its furthest from center, in pixels
    const ART_SIDE_BLUR = 3;

    // Side covers are drawn slightly smaller so they look like they sit behind
    // the playing cover, 1 is the same size as the main cover
    const ART_SIDE_SCALE = 0.8;

    // How many covers to keep ready on each side, two lets a swipe pull the next
    // one in from beyond the edge
    const ART_SIDE_TILES = 2;

    // How long a song change from a button, Bluetooth or the end of a song
    // takes to slide the covers along, like a swipe
    const ART_AUTO_GLIDE = 300;

    // localStorage key that remembers whether the panel is minimized
    const MINIMIZED_KEY = "mureka_player_minimized";

    // localStorage key that remembers the panel position
    const POS_KEY = "mureka_player_pos";

    // localStorage key that remembers the panel width and list height
    const SIZE_KEY = "mureka_player_size";

    // localStorage key that remembers the user settings object
    const SETTINGS_KEY = "mureka_player_settings";

    // localStorage key that enables developer only features like Copy JSON
    // Toggle from the console with localStorage.setItem("mureka_player_debug", "1")
    const DEBUG_KEY = "mureka_player_debug";

    // localStorage key that remembers which songs have been downloaded to disk
    // The extension cannot read the download folder, so we track requests here
    const DOWNLOADED_KEY = "mureka_player_downloaded";

    // localStorage key that remembers the logged in user id once it is learned
    // It is read from the account's own feed so the followed creators list can load
    const SELF_KEY = "mureka_player_self";

    // localStorage key that remembers creators added by hand in the picker
    const CREATORS_KEY = "mureka_player_creators";

    // localStorage key that remembers the last source, the account's own
    // feed or a creator
    const SOURCE_KEY = "mureka_player_source";

    // localStorage key that remembers the play queue across restarts
    const QUEUE_KEY = "mureka_player_queue";

    // Shared style for the floating dropdowns, positioned and shown at runtime
    const POPUP_CSS = [
        "position:fixed",
        "z-index:1000001",
        "background:#26262c",
        "color:#fff",
        "font:13px/1.4 sans-serif",
        "border:1px solid #3a3a42",
        "border-radius:8px",
        "box-shadow:0 8px 24px rgba(0,0,0,0.5)",
        "padding:8px",
        "box-sizing:border-box",
        "display:none",
        "flex-direction:column",
        "gap:6px"
    ].join(";");

    // User settings, loaded once on startup, published is the default start feed
    // Why the stored settings could not be read on start, empty when they
    // were, and whether settings kept aside after such a failure were
    // brought back
    let settingsReadFailed = "";
    let settingsRestored = false;

    // The stored settings put aside after a failed read, and a save that
    // did not go through, so it is said once
    let settingsKeptAside = false;
    let settingsSaveFailed = false;

    // The song's progress on the waveform: a color as #rrggbb and how much
    // it shows, in percent. One up to the play head, and one past it
    const PROGRESS_COLOR = ACCENT;
    const PROGRESS_ALPHA_DEFAULT = 100;

    // The progress past the play head once had a grey of its own. Now it
    // comes with the played part's color, and the old grey kept as a value
    // counts as never changed
    const PROGRESS_AHEAD_OLD = "#a8a8a8";
    const PROGRESS_AHEAD_ALPHA = 100;
    const PROGRESS_ALPHA_MAX = 100;

    // The waveform's own colors, played and still to play. The web view's
    // played part is a light grey unless changed
    const WAVE_PLAYED_COLOR = "#488084";
    const WEB_WAVE_PLAYED_COLOR = "#c8c8d0";

    // The web view's lyric line spacing and position unless changed
    const WEB_LYRIC_LINE = 1.6;
    const WEB_LYRIC_SHIFT = 60;
    const WAVE_REST_COLOR = "#666666";

    // The play head's color and share as they came
    const PLAY_HEAD_COLOR = "#ffffff";
    const PLAY_HEAD_ALPHA = 60;

    // The waveform's colors as they came, by their settings: the color,
    // its share and their values, for the mobile player. The web view's
    // have web before them
    const WAVE_COLOR_DEFAULTS = [
        ["waveColor", "waveAlpha", WAVE_PLAYED_COLOR, 100],
        ["waveRestColor", "waveRestAlpha", WAVE_REST_COLOR, 100],
        ["playHeadColor", "playHeadAlpha", PLAY_HEAD_COLOR, PLAY_HEAD_ALPHA],
        ["waveZoomProgressColor", "waveZoomProgressAlpha", PROGRESS_COLOR, PROGRESS_ALPHA_DEFAULT],
        ["waveZoomProgressAheadColor", "waveZoomProgressAheadAlpha", WAVE_PLAYED_COLOR, PROGRESS_AHEAD_ALPHA]
    ];

    function progressColor(v, fallback) {
        return typeof v === "string" && /^#[0-9a-f]{6}$/i.test(v) ? v.toLowerCase() : (fallback || "#ffffff");
    }

    // The progress past the play head, the old grey taken as unchanged
    function aheadColor(v, fallback) {

        const c = progressColor(v, fallback);

        return c === PROGRESS_AHEAD_OLD ? fallback : c;
    }

    function progressAlpha(v, fallback) {

        const n = Number(v);

        if (isFinite(n) && v !== null && v !== undefined && v !== "") {
            return Math.max(0, Math.min(PROGRESS_ALPHA_MAX, Math.round(n)));
        }

        return typeof fallback === "number" ? fallback : PROGRESS_ALPHA_DEFAULT;
    }

    // The ways the song's progress can show on the zoomed waveform, with
    // what they mean, for the phone's and the web view's settings alike
    const PROGRESS_LOOK_CHOICES = [
        { value: "over", label: "Bar over the waveform" },
        { value: "under", label: "Bar behind the waveform" },
        { value: "wave", label: "Color the waveform" },
        { value: "off", label: "Off" }
    ];
    const PROGRESS_LOOK_HINT = "How far into the whole song it is, from the waveform's left edge: a bar over the "
        + "waveform across its full height, the same bar behind it so the waveform's colors stay as they are, or the "
        + "waveform itself colored instead. Zoomed out it lies on the played part. Zoomed in it still shows the whole "
        + "song, and its edge can be dragged at any height to move through it, the waveform following, as on the thin "
        + "line at its foot.";
    const PROGRESS_COLOR_HINT = "The color of the progress on the played part, left of the play head, and how much "
        + "of it shows. Coloring the waveform, the waveform takes it there instead of its own colors, and the thin "
        + "line at its foot takes it too.";
    const WAVE_COLOR_HINT = "The waveform's color left of the play head, and how much of it shows. The quieter "
        + "outer part of the waveform from the song takes it darker, and the thin line at its foot zoomed in takes it "
        + "too.";
    const WAVE_REST_HINT = "The waveform's color right of the play head, still to play, and how much of it shows.";
    const PLAY_HEAD_HINT = "The thin line across the waveform where the song is, and how much of it shows.";
    const PROGRESS_AHEAD_HINT = "The color of the progress where it reaches past the play head, on the part still "
        + "to come in view.";

    // Where the play head is on the zoomed waveform: in the middle with the
    // waveform sliding under it, or moving along the view as the song goes,
    // from the left edge at its start to the right edge at its end, as when
    // zoomed out. Moving along, the song's progress ends at the play head
    // as it does zoomed out, so the thin line at the foot and the color past
    // the play head are left out
    const PLAY_HEAD_MODES = ["center", "travel"];
    const PLAY_HEAD_MODE_CHOICES = [
        { value: "center", label: "Stays in the middle" },
        { value: "travel", label: "Moves along the song" }
    ];
    const PLAY_HEAD_MODE_HINT = "Zoomed in, the play head either stays in the middle while the waveform slides "
        + "under it, with the whole song as a thin line at its foot, or moves along as the song goes: at the left "
        + "edge at the start, in the middle halfway and at the right edge at the end, as zoomed out. Moving along, "
        + "everything left of it is played and in the played colors, as zoomed out, so the thin line and the color "
        + "past the play head are left out.";

    // BEGIN SHARED wave
    // Written by embed-webview.sh from src/shared/wave.js. Change that
    // file and run make embed, never the lines up to END SHARED wave
    // Drawing a song's waveform, its progress and the play head.
    // Shared by the player and the web view's page, src/shared/wave.js,
    // inlined into both by embed-webview.sh

    // Our own waveform: the peaks dim, and in front of them how loud the
    // song sounds, bright, a column per screen pixel. Played in the accent
    // color, the rest grey. start and span the part of the song in view,
    // each column keeping its place in the song as the view moves
    function drawLayeredWave(ctx, w, h, peaks, loud, frac, start, span, color) {

        const room = h - 1;
        const from0 = start || 0;
        const step = (span || 1) / w;

        for (let k = Math.floor(from0 / step + 1e-9); ; k++) {

            const from = k * step;
            const x = Math.round((from - from0) / step);

            if (from >= 1 || x >= w) {
                break;
            }

            const to = Math.min(1, from + step);
            const played = from + step / 2 <= frac;
            const p = waveSlice(peaks, from, to);
            const l = Math.min(p, waveSlice(loud, from, to) * 0.95);
            const ph = Math.max(1, p * room);
            const lh = Math.max(1, l * room);

            ctx.fillStyle = color(played, x, "dim");
            ctx.fillRect(x, (h - ph) / 2, 1, ph);
            ctx.fillStyle = color(played, x, "loud");
            ctx.fillRect(x, (h - lh) / 2, 1, lh);
        }
    }

    // A thin play head across the waveform at x in its color, down to the
    // thin progress line when zoomed in and the full height when not
    function drawPlayHead(ctx, w, h, x, dpr, foot, fill) {

        if (x >= 0 && x < w) {

            ctx.fillStyle = fill;
            ctx.fillRect(Math.min(x, w - Math.max(1, Math.round(dpr))), 0, Math.max(1, Math.round(dpr)), h - foot);
        }
    }

    // Mureka's waveform as bars, each the highest point of its slice. Each
    // bar keeps its place in the song, so zoomed in they slide along rather
    // than change height as the view moves
    function drawWaveBars(ctx, w, h, data, frac, start, span, barW, gap, dpr, color) {

        const pitch = barW + gap;
        const count = Math.max(1, Math.floor(w / pitch));
        const step = span / count;

        for (let k = Math.floor(start / step + 1e-9); ; k++) {

            const from = k * step;
            const x = Math.round((from - start) / step * pitch);

            if (from >= 1 || x >= w) {
                break;
            }

            const peak = waveSlice(data, from, Math.min(1, from + step));
            const bh = Math.max(2 * dpr, peak * (h - 2 * dpr));

            ctx.fillStyle = color(from + step / 2 <= frac, x, "bar");
            ctx.fillRect(x, (h - bh) / 2, barW, bh);
        }
    }

    // Zoomed in, the whole song as a thin progress line along the foot of
    // the waveform, the part played in played, a little lighter than the
    // played waveform or as the waveform colored by the progress is, and
    // the rest dim. How far it is zoomed shows in the waveform
    function drawWaveOverview(ctx, w, h, frac, dpr, played) {

        const lh = waveFootHeight(dpr);
        const done = Math.round(Math.max(0, Math.min(1, frac)) * w);

        ctx.fillStyle = "rgba(255, 255, 255, 0.12)";
        ctx.fillRect(done, h - lh, w - done, lh);
        ctx.fillStyle = played;
        ctx.fillRect(0, h - lh, done, lh);
    }

    // Zoomed in, how far into the whole song it is, from the left edge and
    // the full height, as if the waveform were the song's progress bar. One
    // color over the played part, left of the play head at headX, and
    // another where it reaches past the play head
    function drawWaveProgress(ctx, w, h, frac, fill, ahead, headX) {

        const end = Math.round(Math.max(0, Math.min(1, frac)) * w);
        const split = Math.max(0, Math.min(end, headX));

        ctx.fillStyle = fill;
        ctx.fillRect(0, 0, split, h);

        if (end > split) {

            ctx.fillStyle = ahead;
            ctx.fillRect(split, 0, end - split, h);
        }
    }

    // Draw the waveform bars, played part cyan, optionally previewing a seek
    // Zooming into a waveform. Pinch, the mouse wheel over it, or a press
    // held still a moment and then slid up or down zooms in and out, and a
    // double tap goes back to the whole song. Zoomed in, the
    // play head stays in the middle and the waveform moves under it, off
    // the middle only near the start and the end. Dragging moves the play
    // head as before. Past two thirds of the way to an edge with more song
    // beyond it, the play head stays there and the waveform scrolls
    // instead, faster the nearer the finger is to the edge. With the play
    // head moving along the song, it goes with the finger right out to the
    // edge, and the waveform scrolls on much faster out there. Let go, the
    // waveform glides back so the play head is in the middle again. A tap
    // zoomed in seeks a moment later, so a second tap can zoom out instead.
    // hooks: ready() a song to seek in, zoomable() a waveform shown,
    // playFrac() where it plays, rect() the box the waveform fills,
    // preview(frac) while dragging and preview(null) when that stops,
    // commit(frac) to seek, redraw() after a change of the view, and when
    // given zoomed(zoom) after the zoom changed
    function makeWaveZoom(el, hooks) {

        const ZOOM_MAX = 32;
        const EDGE = 2 / 3;
        const EDGE_SPEED = 1.5;

        // With the play head moving along, the finger takes it right out to
        // the edge, and the waveform scrolls on the faster the further out
        // it is: from a crawl past two thirds to the whole song in about
        // this many seconds at the very edge, however far zoomed in
        const EDGE_SONG_SEC = 3;
        const GLIDE_MS = 350;
        const DOUBLE_TAP_MS = 300;
        const TAP_MOVE = 6;
        const HOLD_MS = 350;
        const HOLD_ZOOM_PX = 90;
        const GRAB_PX = 24;
        const EASE_PART = 0.3;
        const z = { zoom: 1, drag: null, held: null, glide: null, pinch: null, tap: null, tapTimer: 0, eatUp: false,
            holdTimer: 0, holdZoom: null };
        const pointers = new Map();

        function span() {
            return hooks.zoomable() ? 1 / z.zoom : 1;
        }

        function clampStart(s) {
            return Math.max(0, Math.min(1 - span(), s));
        }

        // Whether the play head moves along the view instead of staying in
        // the middle
        function travels() {
            return !!(hooks.travel && hooks.travel());
        }

        // The view with the play head in the centre, eased near the ends
        // of the song: the play head glides in from the edge to the centre
        // and out again while the waveform speeds up and slows down to
        // match, instead of both changing pace at once
        function follow(frac) {

            const s = span();
            const room = 1 - s;

            // Moving along the song, the play head is as far across the view
            // as the song has come, so the view moves with it at an even pace
            if (travels()) {
                return clampStart(Math.max(0, Math.min(1, frac)) * room);
            }

            const w = Math.min(s * EASE_PART, room / 2);
            const u = frac - s / 2;

            if (w <= 0) {
                return clampStart(u);
            }

            if (u <= -w) {
                return 0;
            }

            if (u < w) {
                return (u + w) * (u + w) / (4 * w);
            }

            if (u <= room - w) {
                return u;
            }

            if (u < room + w) {
                return room - (room + w - u) * (room + w - u) / (4 * w);
            }

            return room;
        }

        // Where the pointer is across the waveform, 0 at the left edge and
        // 1 at the right, beyond those when the pointer is outside it
        function across(ev) {

            const r = hooks.rect();

            return r.width > 0 ? (ev.clientX - r.left) / r.width : 0;
        }

        function spread() {

            const xs = Array.from(pointers.values());

            return Math.max(1, Math.abs(xs[0] - xs[1]));
        }

        function setZoom(v) {

            const was = z.zoom;

            z.zoom = Math.max(1, Math.min(ZOOM_MAX, v));

            if (z.zoom < 1.03) {
                z.zoom = 1;
            }

            if (z.zoom !== was) {

                hooks.redraw();

                if (hooks.zoomed) {
                    hooks.zoomed(z.zoom);
                }
            }
        }

        function dropTap() {

            clearTimeout(z.tapTimer);
            z.tapTimer = 0;
            z.tap = null;
        }

        // A tap still waiting seeks now, a press elsewhere came before the
        // moment it waits for was over
        function flushTap() {

            const t = z.tap;
            const waiting = !!z.tapTimer;

            dropTap();

            if (waiting && t) {

                z.glide = { from: z.held ? z.held.start : 0, at: performance.now() };
                z.held = null;
                hooks.commit(t.frac);
            }
        }

        z.span = span;
        z.setZoom = setZoom;

        // The start of the part of the song in view, as a fraction, with the
        // play head at frac
        z.start = function (frac) {

            if (span() >= 1) {
                return 0;
            }

            // Dragging along the progress line, the view follows the play head
            if (z.drag && z.drag.overview) {
                return follow(frac);
            }

            if (z.drag || z.held) {
                return clampStart((z.drag || z.held).start);
            }

            const target = follow(frac);

            if (z.glide) {

                const k = Math.min(1, (performance.now() - z.glide.at) / GLIDE_MS);

                if (k >= 1) {
                    z.glide = null;
                } else {
                    return clampStart(z.glide.from + (target - z.glide.from) * (1 - Math.pow(1 - k, 3)));
                }
            }

            return target;
        };

        z.dragging = function () {
            return !!z.drag;
        };

        // Whether the view moves by itself, so it is drawn every frame
        z.moving = function () {
            return span() < 1 && (!!z.drag || !!z.glide);
        };

        // The play head while dragging, the view scrolled on by the time
        // since the last call when the finger is past two thirds of the way
        // to an edge with song beyond it
        z.dragFrac = function () {

            const d = z.drag;

            if (!d) {
                return 0;
            }

            // Along the progress line it is the whole song across
            if (d.overview) {
                return Math.max(0, Math.min(1, d.px));
            }

            const now = performance.now();
            const dt = Math.min(0.1, (now - d.at) / 1000);
            const sp = span();
            let px = Math.max(0, Math.min(1, d.px));

            d.at = now;

            if (sp < 1 && travels()) {

                const right = Math.min(1, (d.px - EDGE) / (1 - EDGE));
                const left = Math.min(1, (1 - EDGE - d.px) / (1 - EDGE));
                const slow = EDGE_SPEED * sp;
                const fast = Math.max(slow, 1 / EDGE_SONG_SEC);

                // Rising from nothing, by the same factor for every bit
                // further out, so the slow end stays fine to aim with
                const speed = function (k) {
                    return k * slow * Math.pow(fast / slow, k);
                };

                if (right > 0 && d.start < 1 - sp) {
                    d.start = clampStart(d.start + speed(right) * dt);
                } else if (left > 0 && d.start > 0) {
                    d.start = clampStart(d.start - speed(left) * dt);
                }
            } else if (sp < 1) {

                const right = (d.px - EDGE) / (1 - EDGE);
                const left = (1 - EDGE - d.px) / (1 - EDGE);

                if (right > 0 && d.start < 1 - sp) {

                    d.start = clampStart(d.start + Math.pow(Math.min(1.5, right), 2) * EDGE_SPEED * sp * dt);
                    px = d.start < 1 - sp ? EDGE : px;
                } else if (left > 0 && d.start > 0) {

                    d.start = clampStart(d.start - Math.pow(Math.min(1.5, left), 2) * EDGE_SPEED * sp * dt);
                    px = d.start > 0 ? 1 - EDGE : px;
                }
            }

            return Math.max(0, Math.min(1, d.start + px * sp));
        };

        el.addEventListener("pointerdown", function (ev) {

            if (!hooks.ready()) {
                return;
            }

            ev.preventDefault();

            // The first finger of a new touch, or the mouse: anything left
            // over from before is forgotten. A finger whose lifting was never
            // heard, Safari dropping it to a system gesture or the page going
            // out of sight, would otherwise turn every later drag into a pinch
            // or a held zoom, and the waveform only zooms
            if (ev.isPrimary) {
                forget();
            }

            pointers.set(ev.pointerId, ev.clientX);

            try {
                el.setPointerCapture(ev.pointerId);
            } catch (e) {
                // Moves outside are then not seen, which only ends the drag
            }

            // A second finger makes it a pinch, the drag is let go
            if (pointers.size === 2) {

                clearTimeout(z.holdTimer);
                z.holdZoom = null;
                flushTap();

                if (z.drag) {

                    z.drag = null;
                    hooks.preview(null);
                }

                z.pinch = hooks.zoomable() ? { dist: spread(), zoom: z.zoom } : null;
                return;
            }

            if (pointers.size > 2 || z.pinch) {
                return;
            }

            const now = performance.now();

            // A second tap soon after one close to it: the whole song again,
            // and the first tap's seek, still waiting, is dropped
            if (z.tap && now - z.tap.at < DOUBLE_TAP_MS && Math.abs(ev.clientX - z.tap.x) < 30) {

                const waiting = !!z.tapTimer;

                dropTap();
                z.eatUp = true;

                if (waiting) {

                    z.held = null;
                    hooks.preview(null);
                }

                setZoom(1);
                return;
            }

            flushTap();
            z.glide = null;

            // Zoomed in, a press on the lowest third, where the progress line
            // runs, moves through the whole song as the waveform does zoomed
            // out. Elsewhere it moves the play head in the part in view
            const box = el.getBoundingClientRect();
            const sp = span();
            const travel = travels();
            let overview = !travel && sp < 1 && box.height > 0 && ev.clientY >= box.bottom - box.height / 3;

            // Zoomed in with the song's progress over the waveform, its edge
            // is grabbed at any height to move through the whole song. The
            // play head comes first when the two are close together. With
            // the play head moving along, the two are one and the same
            if (!overview && !travel && sp < 1 && hooks.edge && hooks.edge()) {

                const r = hooks.rect();
                const pf = hooks.playFrac();
                const headX = r.left + (pf - z.start(pf)) / sp * r.width;
                const edgeX = r.left + pf * r.width;

                if (r.width > 0 && Math.abs(ev.clientX - headX) > GRAB_PX && Math.abs(ev.clientX - edgeX) <= GRAB_PX) {
                    overview = true;
                }
            }

            z.drag = { start: z.start(hooks.playFrac()), px: across(ev), at: now, t0: now, x: ev.clientX, moved: false,
                overview: overview, y: ev.clientY, lastY: ev.clientY, movedY: false };
            hooks.preview(z.dragFrac());

            // Held still a moment, it zooms instead: sliding up zooms in and
            // sliding down zooms out, and letting go seeks nothing. Moved
            // before then, sideways or not, it stays a drag
            const pressed = z.drag;

            clearTimeout(z.holdTimer);

            if (hooks.zoomable()) {

                z.holdTimer = setTimeout(function () {

                    if (z.drag !== pressed || pressed.moved || pressed.movedY || pointers.size !== 1) {
                        return;
                    }

                    z.drag = null;
                    hooks.preview(null);
                    z.holdZoom = { y: pressed.lastY, zoom: z.zoom };

                    try {

                        if (navigator.vibrate) {
                            navigator.vibrate(12);
                        }
                    } catch (e) {
                        // No buzz, the zoom shows it
                    }
                }, HOLD_MS);
            }
        });

        el.addEventListener("pointermove", function (ev) {

            if (!pointers.has(ev.pointerId)) {
                return;
            }

            pointers.set(ev.pointerId, ev.clientX);

            if (z.pinch && pointers.size >= 2) {

                setZoom(z.pinch.zoom * spread() / z.pinch.dist);
                return;
            }

            // Held and sliding: up zooms in, down zooms out
            if (z.holdZoom) {

                setZoom(z.holdZoom.zoom * Math.exp((z.holdZoom.y - ev.clientY) / HOLD_ZOOM_PX));
                return;
            }

            if (z.drag) {

                z.drag.px = across(ev);
                z.drag.lastY = ev.clientY;

                if (Math.abs(ev.clientX - z.drag.x) > TAP_MOVE) {

                    z.drag.moved = true;
                    clearTimeout(z.holdTimer);
                }

                if (Math.abs(ev.clientY - z.drag.y) > TAP_MOVE) {

                    z.drag.movedY = true;
                    clearTimeout(z.holdTimer);
                }

                hooks.preview(z.dragFrac());
            }
        });

        // Every press, pinch and held zoom let go, the play head back where
        // it was if a drag had moved it
        const forget = function () {

            pointers.clear();
            clearTimeout(z.holdTimer);
            z.pinch = null;
            z.holdZoom = null;
            z.eatUp = false;

            if (z.drag) {

                z.drag = null;
                hooks.preview(null);
            }
        };

        const up = function (ev, cancelled) {

            if (!pointers.has(ev.pointerId)) {
                return;
            }

            pointers.delete(ev.pointerId);
            clearTimeout(z.holdTimer);

            // Zoomed by holding and sliding: letting go only ends it
            if (z.holdZoom) {

                z.holdZoom = null;
                return;
            }

            // The pinch ends with its fingers, a finger left on does nothing
            if (z.pinch) {

                if (pointers.size === 0) {
                    z.pinch = null;
                }

                return;
            }

            if (z.eatUp) {

                z.eatUp = false;
                return;
            }

            const d = z.drag;

            if (!d) {
                return;
            }

            const frac = z.dragFrac();
            const now = performance.now();

            z.drag = null;

            if (cancelled) {

                hooks.preview(null);
                return;
            }

            const tap = !d.moved && now - d.t0 < DOUBLE_TAP_MS;

            z.tap = tap ? { at: now, x: d.x, frac: frac } : null;

            // Zoomed in, a tap waits a moment in case a second one follows
            if (tap && span() < 1) {

                z.held = { start: d.overview ? follow(frac) : d.start };
                z.tapTimer = setTimeout(function () {

                    z.tapTimer = 0;
                    z.glide = { from: z.held ? z.held.start : 0, at: performance.now() };
                    z.held = null;
                    hooks.commit(frac);
                }, DOUBLE_TAP_MS);
                return;
            }

            // Along the progress line the view already follows, elsewhere it
            // glides back to the play head
            z.glide = d.overview ? null : { from: d.start, at: now };
            hooks.commit(frac);
        };

        el.addEventListener("pointerup", function (ev) {
            up(ev, false);
        });

        el.addEventListener("pointercancel", function (ev) {
            up(ev, true);
        });

        // A finger taken away from the waveform without a lift ends like a
        // cancel, and a page out of sight ends whatever was going on
        el.addEventListener("lostpointercapture", function (ev) {
            up(ev, true);
        });

        document.addEventListener("visibilitychange", function () {

            if (document.hidden) {
                forget();
            }
        });

        // The mouse wheel or a touchpad pinch over the waveform
        el.addEventListener("wheel", function (ev) {

            if (!hooks.ready() || !hooks.zoomable()) {
                return;
            }

            ev.preventDefault();
            setZoom(z.zoom * Math.exp(-ev.deltaY * (ev.deltaMode === 1 ? 0.05 : 0.0025)));
        }, { passive: false });

        return z;
    }

    function playHeadMode(v) {
        return PLAY_HEAD_MODES.indexOf(v) !== -1 ? v : "center";
    }

    function progressLook(v) {
        return PROGRESS_LOOKS.indexOf(v) !== -1 ? v : "wave";
    }

    // The height of the thin progress line along the waveform's foot
    function waveFootHeight(dpr) {
        return Math.max(1, Math.round(2 * dpr));
    }

    // The colors of the waveform for one drawing: played and still to play
    // as set, and, colored by the song's progress, up to the play head in
    // fill and on to where the progress reaches in ahead, as the bar would
    // lie, each with its share. The painter takes whether a column is
    // played, where it is and which layer: loud, dim or bar. Each color is
    // worked out once a drawing
    function wavePainter(w, frac, headX, played, rest, fill, ahead) {

        const end = fill ? Math.round(Math.max(0, Math.min(1, frac)) * w) : 0;
        const split = Math.max(0, Math.min(end, headX));
        const parts = [rgbaParts(rest), rgbaParts(played), rgbaParts(fill), rgbaParts(ahead)];
        const made = new Map();

        return function (isPlayed, x, layer) {

            let zone = isPlayed ? 1 : 0;

            if (x < split) {
                zone = 2;
            } else if (x < end) {
                zone = 3;
            }

            const key = zone + layer;
            let out = made.get(key);

            if (out === undefined) {

                const t = parts[zone];
                let k = 1;

                if (layer === "dim") {
                    k = WAVE_DIM_SHADE;
                } else if (layer === "bar" && zone === 0) {
                    k = WAVE_BAR_REST_SHADE;
                }

                const shade = function (i) {
                    return Math.round(t.c[i] * k);
                };

                out = "rgba(" + shade(0) + ", " + shade(1) + ", " + shade(2) + ", " + t.a + ")";
                made.set(key, out);
            }

            return out;
        };
    }

    // A value of a waveform over a slice of it, from and to as fractions of
    // the song: the highest point when the slice holds several, and a blend
    // of the two nearest when it is narrower than a point, so a wave with
    // fewer points than the screen has columns has no steps
    function waveSlice(list, from, to) {

        const a = Math.floor(from * list.length);
        const b = Math.floor(to * list.length);

        if (b - a >= 2) {

            let peak = 0;

            for (let j = a; j < b; j++) {

                if (list[j] > peak) {
                    peak = list[j];
                }
            }

            return peak;
        }

        const at = (from + to) / 2 * list.length - 0.5;
        const i = Math.max(0, Math.min(list.length - 1, Math.floor(at)));
        const k = Math.max(0, Math.min(1, at - i));
        const next = list[Math.min(list.length - 1, i + 1)];

        return list[i] * (1 - k) + next * k;
    }

    // The way an eased scroll goes. A long way would race past at the end
    // and seem to stop dead, so only a few screens of it are travelled: the
    // first half of them from where it starts, the second half up to where
    // it ends, the part between skipped while it moves fastest. length is
    // how far it seems to go, at(eased) where it is for 0 to 1 of the way
    function easePath(from, to, view) {

        const way = Math.abs(to - from);
        const dir = to < from ? -1 : 1;
        const seen = Math.min(way, Math.max(400, view * 4));

        return {
            length: seen,
            at: function (eased) {

                const v = seen * eased;
                const done = v <= seen / 2 ? v : way - (seen - v);

                return from + dir * done;
            }
        };
    }
    // END SHARED wave

    // How the song's progress shows on the waveform: a bar over it, a bar
    // behind it, the waveform itself colored, or not at all. Kept under a
    // name of its own since 1.9.9.343, so a look saved while a bar was what
    // came is not kept, and the waveform colored is what comes
    const PROGRESS_LOOKS = ["over", "under", "wave", "off"];

    // The color and its share as one fill for the canvas
    function progressFill(color, alpha) {

        const c = progressColor(color);

        return "rgba(" + parseInt(c.slice(1, 3), 16) + ", " + parseInt(c.slice(3, 5), 16) + ", "
            + parseInt(c.slice(5, 7), 16) + ", " + (progressAlpha(alpha) / 100) + ")";
    }

    let settings = loadSettings();

    // Debug overlay, declared early since anything can log from the start.
    // A see-through layer over the whole page that lists what happens as it
    // happens: keys, taps, media buttons, commands from the app, the audio
    // element's events, fullscreen and visibility, with live numbers at the
    // top. It never takes a tap. Nothing in it receives pointer events, so
    // every touch and click goes to what is underneath
    let debugOverlayEl = null;
    let debugStateEl = null;
    let debugLogEl = null;
    let debugTimer = null;

    // The event log, newest last. It is kept with the overlay off as well,
    // so switching it on shows what just happened
    const DEBUG_LOG_KEEP = 300;
    const DEBUG_LOG_SHOW = 80;
    const debugLog = [];

    // The last lines of the log are kept in the tab's own storage while the
    // log is on. Safari reloads a page it had to close, and the log of the
    // page before then comes first in the new one, marked as such
    const DEBUG_LOG_TAB_KEY = "mureka_player_debug_before";
    const DEBUG_LOG_TAB_LINES = 150;
    let debugLogTabTimer = 0;

    try {

        const before = JSON.parse(sessionStorage.getItem(DEBUG_LOG_TAB_KEY) || "null");

        sessionStorage.removeItem(DEBUG_LOG_TAB_KEY);

        if (before && Array.isArray(before.lines) && before.lines.length > 0) {

            debugLog.push("--- before the page was opened again, " + new Date(before.at).toLocaleTimeString() + " ---");

            for (const line of before.lines.slice(-DEBUG_LOG_TAB_LINES)) {
                debugLog.push(String(line));
            }

            debugLog.push("--- this page ---");
        }
    } catch (e) {
        // No storage for the tab, the log starts empty
    }

    function keepDebugLogInTab() {

        if (debugLogTabTimer) {
            return;
        }

        debugLogTabTimer = setTimeout(function () {

            debugLogTabTimer = 0;

            try {
                sessionStorage.setItem(DEBUG_LOG_TAB_KEY, JSON.stringify({
                    at: Date.now(),
                    lines: debugLog.slice(-DEBUG_LOG_TAB_LINES)
                }));
            } catch (e) {
                // Full or not allowed, the log stays in this page only
            }
        }, 1000);
    }

    // What the debug overlays log, in groups to pick from under Developer,
    // each with the kinds of lines it covers and what that is in words. The
    // same list serves the web view, which is sent the kinds left out. A
    // kind in no group is always logged
    const DEBUG_GROUPS = [
        { id: "keys", name: "Keys and taps", kinds: ["Key", "Press", "Click", "Wheel", "Pad"],
            hint: "Keys, taps and clicks, the steering wheel and game pads." },
        { id: "media", name: "Media buttons", kinds: ["Media"],
            hint: "Play, pause, next and the others from Bluetooth, the lock screen and media keys, as they arrive." },
        { id: "bluetooth", name: "Bluetooth", kinds: ["Bluetooth"], app: true,
            hint: "Bluetooth audio connecting and going away, and what the player does about it." },
        { id: "cover", name: "Cover", kinds: ["Cover"],
            hint: "Every cover sent to the car and the lock screen, and whether the cover downloaded." },
        { id: "playback", name: "Playback", kinds: ["Song", "Audio", "Status", "Phone"],
            hint: "Song changes, playing and pausing, the audio element and the status line." },
        { id: "commands", name: "Commands", kinds: ["Command", "Send"], app: true,
            hint: "What the web view asks the Android device to do." },
        { id: "screen", name: "Screen and page", kinds: ["Screen", "Page", "Size"],
            hint: "The screen, fullscreen, the page showing or hiding, and its size." },
        { id: "settings", name: "Setting changes", kinds: ["Setting"],
            hint: "Each setting changed, from what to what." },
        { id: "power", name: "Power saving", kinds: ["Power", "Hotspot", "WireGuard", "VPN"], app: true,
            hint: "The charger and the chosen Bluetooth devices coming and going, the countdown, the hotspot and the background work stopping and starting." },
        { id: "network", name: "Network", kinds: ["Net", "Offline"],
            hint: "Going online and offline, and the Android device not answering the web view.",
            plainHint: "Going online and offline." },
        { id: "errors", name: "Errors", kinds: ["Error"],
            hint: "Errors in the page." },
        { id: "mureka", name: "Mureka requests", kinds: ["Mureka"],
            hint: "Every request to Mureka's server from the page, the player's and those of Mureka's own site, and what a play report got back. Play a song in Mureka's own player to see what it sends." }
    ];

    // The kinds of lines left out by the groups switched off
    function debugHiddenKinds() {

        const hide = Array.isArray(settings.debugHide) ? settings.debugHide : [];
        const out = [];

        for (const group of DEBUG_GROUPS) {

            if (hide.indexOf(group.id) >= 0) {
                out.push.apply(out, group.kinds);
            }
        }

        return out;
    }

    // The status line's last text, each new one is logged once
    let debugLastStatus = "";

    // The last browsed source, used to reopen on the account's own feed or a
    // creator when
    // the player is set to start where it was left. Set to published or all,
    // it always opens the account's own library that way
    let startupSource = settings.startFeed === "last" ? loadSource() : null;

    // Honor the remembered feed, or the chosen start feed, before its cache loads
    // A remembered creator is applied after the UI is built, see applyStartupSource
    publishFilter = (startupSource && startupSource.kind === "feed")
        ? (["published", "all", "drafts"].indexOf(startupSource.feed) >= 0 ? startupSource.feed : "published")
        : (settings.startFeed === "all" ? "all" : "published");

    // The creator whose library is being browsed, or null for the account's own library
    // When set, feed() returns a creator config so the loader and cache follow it
    // This must be declared before the cache is loaded below, because loadCache
    // calls feed(), which reads creatorSource. A later declaration would leave it
    // in its temporal dead zone, making feed() throw and the cache load come up
    // empty, which forced a full reload on every startup
    let creatorSource = null;

    // Counts every save of what the exports hold, the song list and the
    // song tweaks, so the web view fetches them again only once they changed
    let exportsVersion = 0;

    // Saving the song list failed since then, and when it was last said
    const STORAGE_WARN_MS = 3 * 60 * 1000;
    let storageProblemAt = 0;
    let storageWarnedAt = 0;

    // What to say about a stored song list that could not be read
    let brokenLibraryNote = "";

    // Cached data, loaded once on startup
    // A song list of thousands of songs outgrows what a browser keeps for a
    // site, about 5 MB on Safari, shared with Mureka's own page. From this
    // size on it is stored packed, about a ninth of the room. Smaller lists
    // stay plain text
    const PACK_FROM = 250000;
    const PACK_MARK = "\u0001W1";

