    // time, Play, Shuffle and a way back to all songs
    let playlistHeadEl = null;

    // The logged in user id, learned from the account's own feed, used to
    // list the creators the account follows
    let selfUserId = loadSelfUserId();

    // Counts the New marks taken off, so the web view knows to repaint its rows
    let playedMarks = 0;

    // Counts renames, so a web view knows to write the titles in its list again
    let songEdits = 0;

    // Creators the account follows plus any added by hand, loaded on demand
    // into the picker
    let followedCreators = [];
    let savedCreators = loadSavedCreators();

    // True while the followed creators list is loading
    let creatorsLoading = false;

    // Live filter text for the creator picker, lowercased, empty shows all
    let creatorQuery = "";

    // Play, favorite and share counts for the now playing song, or null
    let nowPlayingCounts = null;

    // Whether the floating action and view dropdowns are open
    // Both start closed so the panel opens compact every time
    let actionsOpen = false;

    // True while the settings panel is on screen, so the blackout holds off
    let settingsOpen = false;

    // Every settings row registers a redraw here, so opening the panel can put
    // all of them back in step with what is actually stored
    const settingsRefreshers = [];

    // The gaps between the phone's volume steps being trained by ear
    let volTraining = false;

    let viewMenuOpen = false;

    // True while a load run is in progress
    let running = false;

    // The last raw feed response, kept for the debug Copy last feed JSON action
    let lastFeedResponse = null;

    // Identifies the active load run, bumped to cancel a run and to stop a load
    // that started on one feed from writing into another after a feed switch
    let loadToken = 0;

    // True while a cache-all run is in progress
    let cacheRunning = false;

    // The last Load or Rescan that could not reach Mureka, cleared by the
    // next one of the same kind that gets through. Both the Load and Rescan
    // buttons and the web view show it in red
    let loadFail = null;
    let runFailed = false;

    // A failed request in words. A name that does not resolve, no network
    // at all and a refused connection all arrive as the same TypeError
    function describeNetError(e) {

        const msg = e && e.message ? String(e.message) : "";

        if (e && e.name === "AbortError") {
            return "Mureka did not answer in time";
        }

        if (/^HTTP \d+/.test(msg)) {
            return "Mureka answered " + msg;
        }

        if (/^Mureka code /.test(msg)) {
            return "Mureka answered with an error (" + msg.slice(12) + ")";
        }

        return "could not reach mureka.ai, check the connection";
    }

    function noteLoadFail(kind, e) {

        runFailed = true;
        loadFail = { kind: kind === "rescan" ? "rescan" : "load", why: describeNetError(e), at: Date.now() };
        updateButton();
        publishHostSoon();
    }

    function clearLoadFail() {

        if (!loadFail) {
            return;
        }

        loadFail = null;
        updateButton();
        publishHostSoon();
    }

    // What the player is working through right now, for the web view's
    // progress bar. Total 0 means the size is not known in advance
    let hostProgress = null;

    let progressStarted = 0;
    let progressKind = "";

    function setProgress(kind, label, done, total) {

        if (kind && kind !== progressKind) {
            progressStarted = Date.now();
        }

        progressKind = kind || "";
        hostProgress = kind ? { kind: kind, label: label, done: done, total: total } : null;
        publishHostSoon();
        paintProgress();
    }

    // The same progress over the list here as the web view shows: what is
    // going on, how far it is, for how long and about how long is left, and
    // a bar when the size is known
    let progressEl = null;
    let progressTextEl = null;
    let progressFillEl = null;
    let progressBarEl = null;
    let progressStopEl = null;
    let progressTimer = 0;

    function buildProgress() {

        progressEl = document.createElement("div");
        progressEl.style.cssText = "display:none;margin-top:6px;color:" + ACCENT + ";font-size:12px";

        const line = document.createElement("div");
        line.style.cssText = "display:flex;align-items:center;gap:7px;min-width:0";

        const ring = document.createElement("span");
        ring.style.cssText = "flex:0 0 auto;width:10px;height:10px;border:2px solid rgba(" + ACCENT_RGB + ",0.3);border-top-color:" + ACCENT + ";border-radius:50%;animation:mureka-spin 0.9s linear infinite";

        progressTextEl = document.createElement("span");
        progressTextEl.style.cssText = "flex:1 1 auto;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis";

        line.appendChild(ring);
        line.appendChild(progressTextEl);

        // Whatever runs is stopped from here too: a load, a rescan, caching
        // or the reading of play counts
        progressStopEl = document.createElement("button");
        progressStopEl.type = "button";
        progressStopEl.textContent = "Stop";
        progressStopEl.title = "Stop";
        progressStopEl.style.cssText = "flex:0 0 auto;padding:2px 10px;border:0;border-radius:10px;background:transparent;"
            + "box-shadow:inset 0 0 0 1.5px " + DANGER + ";color:" + DANGER + ";font-size:12px;cursor:pointer";
        progressStopEl.addEventListener("click", stopProgressJob);
        line.appendChild(progressStopEl);

        progressBarEl = document.createElement("div");
        progressBarEl.style.cssText = "margin-top:5px;height:4px;border-radius:2px;background:#333;overflow:hidden";

        progressFillEl = document.createElement("div");
        progressFillEl.style.cssText = "height:100%;width:0;background:" + ACCENT + ";border-radius:2px;transition:width 0.3s ease";

        progressBarEl.appendChild(progressFillEl);
        progressEl.appendChild(line);
        progressEl.appendChild(progressBarEl);

        return progressEl;
    }

    function paintProgress() {

        if (!progressEl) {
            return;
        }

        const p = hostProgress;

        if (!p) {

            progressEl.style.display = "none";
            clearInterval(progressTimer);
            progressTimer = 0;
            return;
        }

        const done = Number(p.done) || 0;

        // A rescan's size is a guess from before, a library that grew since
        // simply counts on past it
        const total = Number(p.total) > 0 ? Math.max(Number(p.total), done) : 0;
        const secs = Math.max(0, Math.round((Date.now() - progressStarted) / 1000));

        let timing = formatTime(secs);

        if (secs > 3 && total > 0 && done > 0 && done < total) {

            const left = Math.round((total - done) * secs / done);

            timing += ", about " + (left >= 90 ? Math.round(left / 60) + " min" : Math.max(5, Math.round(left / 5) * 5) + " s") + " left";
        }

        // A rescan only guesses the size from what the library had before
        const rough = p.kind === "rescan" ? "of about " : "of ";

        progressTextEl.textContent = p.label + (total > 0
            ? " " + done + " " + rough + total
            : (done > 0 ? " " + done : "")) + " (" + timing + ")";

        progressBarEl.style.display = total > 0 ? "block" : "none";
        progressFillEl.style.width = total > 0 ? Math.round(Math.max(0, Math.min(1, done / total)) * 100) + "%" : "0";
        progressEl.style.display = "block";

        // The clock keeps counting between the steps
        if (!progressTimer) {
            progressTimer = setInterval(paintProgress, 1000);
        }
    }

    // Object URL of the blob currently feeding the audio element, for cleanup
    let currentObjectUrl = null;

    // A playable URL prepared for the song coming up next, resolved from the
    // cache while the current song is still playing. Starting the next song in
    // the background only works if play is called without waiting on anything
    // first, and this is what makes that possible even with no signal
    let nextReady = null;

    // Incremented on each play, lets a slow blob fetch know it is now stale
    let playToken = 0;

    // The song object currently playing, null when nothing plays
    let currentSong = null;

    // Cache of recent cover images by song id, held as data urls so returning
    // to a recent track shows its art at once without a refetch. Data urls carry
    // the bytes inline, avoiding the blob url loading and memory bugs on iOS
    const ART_CACHE_MAX = 5;
    const artCache = new Map();

    // Rising token so a slow cover fetch learns a newer track has taken over
    let artFetchToken = 0;

    // Shared audio element for the built in player
    let audio = null;

    // The sound engine and the gain a song goes through on an iPhone or iPad
    // for a fade, see wireIosGain
    let iosCtx = null;
    let iosGain = null;

    // What reaches the speaker, read to tell a silent engine from a quiet
    // song, and the check of it while a song plays
    let iosMeter = null;
    let iosMeterBuf = null;
    let iosWatchTimer = 0;
    let iosWatchLast = null;
    let iosStillTicks = 0;
    let iosSilentTicks = 0;
    let iosGoodTicks = 0;
    let iosRestartTried = false;

    // Set when the engine passes no sound on even after a restart. The next
    // tap then makes a new engine and a new element
    let iosEngineDead = false;

