    let songDataStamp = 0;

    // Songs Mureka is still generating, seen on the account's own list pages, by id.
    // Only kept while the player runs. They show greyed at the top of the
    // list, and the first list page is read every few seconds until they
    // are ready. Those asked to play when ready are in pendingPlay, as
    // "now" to play at once or "after" to play once the playing song ends.
    // Those are kept on the device, so a player opened again still plays
    // them when they are ready, for a few hours
    const pendingSongs = new Map();
    const pendingPlay = new Map();
    const PENDING_POLL_MS = 5000;
    const PENDING_PLAY_KEY = "mureka_pending_play";
    const PENDING_PLAY_KEEP_MS = 3 * 3600 * 1000;
    let pendingPlaySaveTimer = 0;

    function savePendingPlaySoon() {

        clearTimeout(pendingPlaySaveTimer);
        pendingPlaySaveTimer = setTimeout(function () {

            try {

                if (pendingPlay.size === 0) {
                    localStorage.removeItem(PENDING_PLAY_KEY);
                } else {

                    localStorage.setItem(PENDING_PLAY_KEY, JSON.stringify({
                        at: Date.now(),
                        plays: Array.from(pendingPlay.entries()),
                        chain: typeof afterChain !== "undefined" ? afterChain.slice() : []
                    }));
                }
            } catch (e) {
                // Kept for this run only
            }
        }, 0);
    }

    // Every change kept at once
    pendingPlay.set = function (k, v) {

        Map.prototype.set.call(this, k, v);
        savePendingPlaySoon();

        return this;
    };
    pendingPlay.delete = function (k) {

        const had = Map.prototype.delete.call(this, k);

        savePendingPlaySoon();

        return had;
    };

    // The ones asked for before the player was opened again, a few hours
    // at most, the order they were asked in with them
    const restoredChain = [];

    (function () {

        try {

            const v = JSON.parse(localStorage.getItem(PENDING_PLAY_KEY) || "null");

            if (!v || !Array.isArray(v.plays) || !(Date.now() - Number(v.at) < PENDING_PLAY_KEEP_MS)) {
                return;
            }

            for (const pair of v.plays) {

                // Play now asked before the player was opened again waits for
                // the song playing by then, rather than cutting it off
                if (Array.isArray(pair) && (pair[1] === "now" || pair[1] === "after")) {
                    Map.prototype.set.call(pendingPlay, String(pair[0]), "after");
                }
            }

            for (const id of Array.isArray(v.chain) ? v.chain : []) {
                restoredChain.push(String(id));
            }
        } catch (e) {
            // Nothing kept
        }
    })();

    // Asked for before and done meanwhile, while the player was closed: in
    // the list now as an ordinary song, played as asked all the same
    function adoptRestoredPending() {

        for (const id of Array.from(pendingPlay.keys())) {

            if (pendingSongs.has(id)) {
                continue;
            }

            const song = cache.songs.find(function (x) {
                return String(x.song_id) === id;
            });

            if (song && !isPendingSong(song)) {

                dbgLog("Song", "asked to play when ready before the player opened again, ready now: " + (song.title || "Untitled"));
                pendingSongs.set(id, { song: song, misses: 0 });
            }
        }
    }

    let pendingTimer = 0;
    let pendingBusy = false;
    let pendingStamp = 0;

    // Two rows for songs asked of Mureka and not listed by it yet, as
    // Mureka's own page shows them, by the send they belong to. Gone once
    // the real songs are listed, the request fails, or after a while
    const sendingSongs = [];
    let sendingSeq = 0;
    const SENDING_LONGEST_MS = 6 * 60000;

    // When true the queue is built and rebuilt in random order
    // Starts from the default play mode chosen in settings
    let shuffleMode = settings.shuffle;

    // Repeat mode, one of all, one or none
    // Starts from the default repeat chosen in settings
    let repeatMode = settings.repeat;

    // Saved playback state so Stop can be resumed by Play
    let resumeState = null;

    // A one-shot seek applied once the next song has loaded, used when resuming
    let pendingSeek = 0;

    // Where a song from its beginning starts on an iPhone or iPad
    const FRESH_START_AT = 0.05;

    // The place a move by loading the song again goes to, shown until the
    // song is there, null otherwise
    let movingTo = null;
    let movingTimer = 0;

    // How far before the place moved to the play head shows it, the delay
    // to the ear, so a song played on goes on from where the play head
    // stood
    let movingLag = 0;

    // Where the song and the sound engine's clock were as the song started
    // playing, for the play head on an iPhone or iPad, see markEngineClock,
    // and how far the play head was from the song's own clock as it paused
    let engineMark = null;
    let seekedThisLoad = false;
    let pauseHold = null;

    // When the playing song was asked to start and when its clock last moved,
    // so a tap on it can tell a song that plays from one that only seems to
    let trackAskedAt = 0;
    let clockMovedAt = 0;
    let clockLast = -1;

    // Timestamp of the last periodic queue save, throttles writes during play
    let lastQueueSave = 0;

    // UI element references
    let statusEl = null;
    let authWarnEl = null;
    let countsEl = null;
    let listEl = null;
    let listWrapEl = null;
    let pullEl = null;
    let toTopBtn = null;

    // A round button over the list that brings the playing song into view,
    // shown only while that song is scrolled out of sight
    let locateBtn = null;

    // Rows are built lazily as the list is scrolled. These hold what the list
    // would show, how many rows of it exist as elements, and the per render
    // facts each row needs. A library of thousands of songs must not become
    // thousands of live elements on every redraw, which is what was running
    // the phone out of memory
    let lazyRows = [];
    let lazyRendered = 0;
    let lazyKeep = 0;
    let lazyKey = "";
    let lazyState = null;

    // How many rows go in at a time
    const RENDER_CHUNK = 120;

    // The panel color, used by the panel, the backdrop behind it and the page
    // backgrounds it takes over, so the three can never drift apart
    const PANEL_BACKGROUND = "#1d1d22";

    // Thin strips in the panel color pinned to the bottom and top edges
    // while the panel is open on a phone, see updateEdgeStrip
    let edgeStripEl = null;
    let topStripEl = null;

    // The panel's top padding while the top strip is shown, a little more
    // than the strip is tall, and the gap under the header then, smaller by
    // the same 5 pixels
    const TOP_STRIP_ROOM = "13px";
    const TOP_STRIP_GAP = "2px";

    // Safari 26 on iOS ignores theme-color. It takes the color of its bottom
    // toolbar from the first fixed or sticky element it finds 8 pixels inside
    // the bottom edge, and uses that element's plain background color. It
    // skips elements 10 pixels tall or less, nearly transparent ones and
    // hidden ones, and without a match it falls back to the page background,
    // which mureka.ai sets to black. The panel alone did not qualify, so this
    // strip gives Safari a fixed element with a plain color at the edge.
    // It sits above the panel so it is the one found, is 11 pixels tall so
    // it is not skipped, and never takes a tap. The top bar is colored the
    // same way from the top edge, which shows once a banner of Safari's own
    // above the page has gone, so a strip goes there too. Folded, the site
    // shows its own bars, so they go
    function updateEdgeStrip(show) {

        // The panel's content starts below the top strip, so the strip,
        // drawn above the panel, never covers its first row. The room it
        // takes is given back from the gap under the header, so everything
        // below it stays where it was
        if (panelEl) {

            if (show) {

                panelEl.style.setProperty("padding-top", TOP_STRIP_ROOM, "important");
                panelEl.style.setProperty("gap", TOP_STRIP_GAP, "important");
            } else {

                panelEl.style.removeProperty("padding-top");
                panelEl.style.removeProperty("gap");
            }
        }

        if (!show) {

            for (const el of [edgeStripEl, topStripEl]) {

                if (el) {
                    el.style.display = "none";
                }
            }

            return;
        }

        const strip = function (id, edge) {

            const el = document.createElement("div");

            el.id = id;
            el.style.cssText = [
                "position:fixed",
                "left:0",
                "right:0",
                edge + ":0",
                "height:11px",
                "z-index:2147483000",
                "pointer-events:none",
                "background-color:" + PANEL_BACKGROUND
            ].join(";");

            (document.body || document.documentElement).appendChild(el);

            return el;
        };

        if (!edgeStripEl) {
            edgeStripEl = strip("mureka-player-edge-strip", "bottom");
        }

        if (!topStripEl) {
            topStripEl = strip("mureka-player-top-strip", "top");
        }

        edgeStripEl.style.display = "block";
        topStripEl.style.display = "block";
    }

    // The padding the phone layout gives the panel
    const PANEL_PAD_MOBILE = "8px";

    // What the page looked like before the panel took its colors over, so it
    // can be handed back untouched the moment the panel folds away
    let savedRootBackground = null;
    let savedThemeColors = null;
    let addedThemeMeta = null;

    // Safari paints the strip around the page, and tints its own toolbars,
    // from the page rather than from anything drawn on top of it. No element
    // can reach those areas, which is why a sheet behind the panel leaves them
    // black. The page itself is asked for the panel color instead, through
    // the root background for the strip and through theme-color for the bars,
    // and both are put back exactly as they were when the panel folds away
    function paintPageBehind(active) {

        const root = document.documentElement;

        if (active && savedRootBackground === null) {
            savedRootBackground = root.style.backgroundColor;
        }

        if (active) {
            root.style.backgroundColor = PANEL_BACKGROUND;
        } else if (savedRootBackground !== null) {

            root.style.backgroundColor = savedRootBackground;
            savedRootBackground = null;
        }

        // A site may ship several of these, one per color scheme, and the one
        // that applies is whichever matches, so they all have to be handled
        let metas = Array.prototype.slice.call(
            document.querySelectorAll('meta[name="theme-color"]'));

        if (active && !metas.length && !addedThemeMeta) {

            addedThemeMeta = document.createElement("meta");
            addedThemeMeta.setAttribute("name", "theme-color");
            document.head.appendChild(addedThemeMeta);
        }

        if (addedThemeMeta) {
            metas = metas.concat([addedThemeMeta]);
        }

        if (active) {

            if (savedThemeColors === null) {

                savedThemeColors = metas.map(function (m) {
                    return m.getAttribute("content");
                });
            }

            metas.forEach(function (m) {
                m.setAttribute("content", PANEL_BACKGROUND);
            });

        } else if (savedThemeColors !== null) {

            metas.forEach(function (m, i) {

                const was = savedThemeColors[i];

                if (was === null || was === undefined) {
                    m.removeAttribute("content");
                } else {
                    m.setAttribute("content", was);
                }
            });

            savedThemeColors = null;
        }
    }

    // True while the on screen keyboard is covering part of the panel. Set by
    // the search field handling, read by the sizing, which must not hand the
    // panel the tall viewport while the keyboard is over the lower half of it
    let keyboardUp = false;

    // iOS Safari zooms the whole page when a focused field has a font smaller
    // than this, and never zooms back out. Every field the user can type into
    // is set to it, which is the only way to refuse that behaviour without
    // disabling pinch zoom for the whole site
    const INPUT_FONT = "16px/1.3 sans-serif";

    // A jump to either end scrolls smoothly for a while, and none of that
    // scrolling is the user, so the edge button must not react to it
    let edgeJumpUntil = 0;

    // Whether the list goes along to the next song when it starts. On until
    // the playing song is scrolled out of sight by hand, on again with the
    // button that finds it
    let listFollow = true;

    // Direction aware scroll button state
    let toTopDir = "up";
    let toTopTimer = 0;
    let lastListScroll = 0;
    let programmaticScrollAt = 0;
    let loadButton = null;
    let rescanButton = null;
    let feedButton = null;
    let cacheButton = null;
    let downloadButton = null;

    // Which button started the run that is going on, "load" or "rescan", so
    // the one that was actually pressed is the one that turns into Stop. Both
    // call into the same loader, and labelling Load as Stop during a rescan
    // pointed at a button the user never touched
    let runOwner = null;

    // The sheet painted behind the panel on phones, see where it is built
    let backdropEl = null;

    // The panel, its header, its collapsible body and the minimize indicator
    let panelEl = null;
    let headerEl = null;
    let selfNameEl = null;

    // The logged in user's stage name, used for the ${artist} template tag
    let selfName = "";

    // Refreshers for the live template previews shown in settings
    let metaPreviewUpdaters = [];
    let sourceSepEl = null;
    let sourceEl = null;
    let bodyEl = null;
    let minimizeBtn = null;

    // The actions menu entry that folds and unfolds the panel, kept so its
    // label and icon can follow the state rather than always saying Hide
    let foldButton = null;
    let webViewButton = null;
    let webViewHeadBtn = null;
    let webViewFloatBtn = null;

    // The menu entry that enters and leaves fullscreen, kept so its label and
    // icon can follow the state
    let fullscreenButton = null;

    // The transport row and the buttons it can hold, keyed by the names used
    // in the controlOrder setting
    let controlRowEl = null;
    let controlButtons = {};

    // The published or all toggle when placed in the transport row
    let publishedCtrlBtn = null;

    // The opener for the smart filter sheet, and the on off switch beside it
    let smartFilterBtn = null;
    let smartToggleBtn = null;

    // The vocals, instrumental or all cycle when placed in the transport row
    let vocalsCtrlBtn = null;
    let setsCtrlBtn = null;

    // The Fold sets button in the list's view menu
    let setFoldBtn = null;
    let nightCtrlBtn = null;
    let eqCtrlBtn = null;
    let nightActionBtn = null;

    // Long press state for rearranging the transport row in the player itself.
    // A short press must still work the button, so nothing moves until the
    // press has been held, and the click that follows a drag is swallowed
    let ctrlDragName = null;
    let ctrlHoldTimer = null;
    let ctrlGhost = null;
    let ctrlGhostDX = 0;
    let ctrlGhostDY = 0;
    let ctrlStartX = 0;
    let ctrlStartY = 0;
    let ctrlSuppressClick = false;
    let ctrlDocMove = null;
    let ctrlDocUp = null;

    // Timestamp of the last header click, so minimize needs a double click
    let lastHeaderClickT = 0;
    let minimized = false;

    // Where the folded panel was dragged to on a phone, measured from the
    // top left of the visible screen. Empty means its place at the top, which
    // is where every fold starts
    let miniPos = null;

    // The right side of the header, whose buttons keep their own taps
    let headerRightEl = null;

    // Current anchor, the side and edge offset are kept so growth keeps the dock
    let anchorLeft = 8;
    let anchorSide = "bottom";
    let anchorOffset = 16;

    // The view buttons, keyed by view name
    let viewButtons = {};

    // The vocals filter buttons, keyed by filter value
    let filterButtons = {};

    // Set of song_ids whose mp3 is present in the audio cache
    let cachedIds = new Set();

    // Set of song_ids whose cover is present in the persistent art store
    let artCachedIds = new Set();

    // Set of song_ids that are being cached right now, shown by a pulsing dot
    let cachingIds = new Set();

    // How far each song being cached has come, 0 to 1, or -1 while its size
    // is not known, for the growing dot in the web view's lists
    const cachingProgress = new Map();

    // A download that brings nothing new for this long is given up. A song
    // just done generating can be served while Mureka still writes it, and
    // such a download may never end. Waiting on it held the song as being
    // stored until the page was opened again, so it was never stored and
    // never got its own waveform
    const DOWNLOAD_STALL_MS = 20000;

    // The same answer, its body counted as it is read, so the progress of a
    // download shows as it is stored. One that stalls, or ends short of the
    // size it gave, fails, so nothing half is kept. An answer that cannot be
    // read this way is handed back as it is
    function trackDownload(song, net) {

        const id = song.song_id;
        const total = Number(net && net.headers ? net.headers.get("Content-Length") : 0) || 0;

        cachingProgress.set(id, total > 0 ? 0 : -1);

        if (!net || !net.body || typeof ReadableStream === "undefined") {
            return net;
        }

        try {

            const reader = net.body.getReader();
            let seen = 0;

            const body = new ReadableStream({
                pull: async function (controller) {

                    let timer = 0;

                    const stalled = new Promise(function (resolve) {
                        timer = setTimeout(function () {
                            resolve(null);
                        }, DOWNLOAD_STALL_MS);
                    });

                    const part = await Promise.race([reader.read(), stalled]);

                    clearTimeout(timer);

                    if (part === null) {

                        dbgLog("Cache", "the download of " + id + " stalled after " + seen + " bytes, given up");
                        reader.cancel("stalled").catch(function () {
                            // Already gone
                        });
                        controller.error(new Error("download stalled"));
                        return;
                    }

                    if (part.done) {

                        if (total > 0 && seen < total) {

                            dbgLog("Cache", "the download of " + id + " ended at " + seen + " of " + total + " bytes, not kept");
                            controller.error(new Error("download ended short"));
                            return;
                        }

                        controller.close();
                        return;
                    }

                    seen += part.value.byteLength;

                    if (total > 0) {
                        cachingProgress.set(id, Math.min(1, seen / total));
                    }

                    controller.enqueue(part.value);
                },
                cancel: function (why) {
                    reader.cancel(why);
                }
            });

            return new Response(body, { status: net.status, statusText: net.statusText, headers: net.headers });
        } catch (e) {
            return net;
        }
    }

    // A song's file read in full, then handed on as an answer held in
    // memory, ready to be stored. Safari stores an answer still streaming
    // in such a way that the copy can later not be read, which left songs
    // marked as stored with no waveform. A stall or a short file fails here,
    // before anything is stored
    async function wholeDownload(song, net) {

        const blob = await trackDownload(song, net).blob();

        return new Response(blob, { status: net.status, statusText: net.statusText, headers: net.headers });
    }

    // A stored copy of a song that cannot be read or decoded is thrown
    // away, so the song is not shown as stored when it is not, and fetched
    // again, once per song for each opening of the page. False when it was
    // thrown away once already, the song itself is then what fails
    const brokenCopies = new Set();

    async function dropBrokenCopy(song, url, why) {

        const id = String(song.song_id);
        const again = !brokenCopies.has(id);

        brokenCopies.add(id);
        dbgLog("Cache", "the stored copy of " + id + " " + why + ", thrown away" + (again ? " and fetched again" : ""));

        try {
            await (await openStore(AUDIO_CACHE)).delete(url, { ignoreVary: true });
        } catch (e) {
            // Gone already, or the store is not there
        }

        if (cachedIds.delete(song.song_id)) {

            saveCacheMarksSoon();
            repaintCacheDot(song);
        }

        if (again) {
            fetchToCache(song, true);
        }

        return again;
    }

    // The browser's stores, each opened once and kept. Opened anew for
    // every read and write, a list page of songs asked Safari for dozens of
    // stores at once, every few seconds while songs were generating, which
    // is the likeliest way its store came to stop answering. One that fails
    // to open is opened anew the next time
    const openStores = new Map();

    // Songs whose waveform from a list page was looked at while the page is
    // open, and the one keeping now, so they are kept one at a time
    const wavesKept = new Set();
    let waveSaving = Promise.resolve();

    // How often a store request failed, was tried again on the store
    // opened anew, and worked then, for the stats and the debug log
    const storeCounts = { failed: 0, retried: 0, recovered: 0 };

    function openStore(name) {

        if (!openStores.has(name)) {
            openStores.set(name, Promise.resolve(storeHandle(name)));
        }

        return openStores.get(name);
    }

    // A store that asks Safari's store object it holds, and when that
    // fails with Safari's internal error, opens the store anew and asks
    // once more. A store object held while the page was in the background
    // can stop answering while a newly opened one answers
    const STORE_REOPEN_MS = 5000;

    function storeHandle(name) {

        let held = null;
        let reopenedAt = 0;

        function cacheNow(fresh) {

            if (fresh || !held) {

                const opening = caches.open(name);

                held = opening;
                opening.catch(function () {

                    if (held === opening) {
                        held = null;
                    }
                });
            }

            return held;
        }

        async function ask(method, args) {

            let first = args;
            let spare = null;

            // A response can be read only once, a copy goes first so the
            // original is left for the second try
            if (method === "put" && args[1] && typeof args[1].clone === "function" && !args[1].bodyUsed) {

                spare = args[1];
                first = [args[0], args[1].clone()];
            }

            try {

                const c = await cacheNow(false);

                return await c[method].apply(c, first);
            } catch (e) {

                if (!isStoreFailure(e)) {
                    throw e;
                }

                // Already known not to answer, or opened anew a moment ago:
                // the request fails as it is, the caller falls back
                if (storeBroken || Date.now() - reopenedAt < STORE_REOPEN_MS) {

                    storeCounts.failed += 1;
                    throw e;
                }

                reopenedAt = Date.now();
                storeCounts.retried += 1;
                dbgLog("Cache", method + " in " + name + " failed (" + errText(e) + "), opening the store anew"
                    + (pageHiddenAt ? ", the page was last hidden " + Math.round((Date.now() - pageHiddenAt) / 1000) + " s ago" : ""));

                try {

                    const c = await cacheNow(true);
                    const out = await c[method].apply(c, spare ? [args[0], spare] : args);

                    storeCounts.recovered += 1;
                    dbgLog("Cache", method + " in " + name + " worked on the store opened anew");
                    return out;
                } catch (e2) {

                    storeCounts.failed += 1;
                    throw e2;
                }
            }
        }

        return {
            add: function () { return ask("add", Array.from(arguments)); },
            addAll: function () { return ask("addAll", Array.from(arguments)); },
            delete: function () { return ask("delete", Array.from(arguments)); },
            keys: function () { return ask("keys", Array.from(arguments)); },
            match: function () { return ask("match", Array.from(arguments)); },
            matchAll: function () { return ask("matchAll", Array.from(arguments)); },
            put: function () { return ask("put", Array.from(arguments)); }
        };
    }

    // When the page was last hidden. The stores held are let go then, so
    // the page opens them anew when it is back
    let pageHiddenAt = 0;

    document.addEventListener("visibilitychange", function () {

        if (document.hidden) {

            pageHiddenAt = Date.now();
            openStores.clear();
        }
    });

    // What is on the screen comes first: the playing song read from the
    // store, its waveform worked out. Work for the lists and the library,
    // checking what is stored, collecting waveforms from list pages,
    // storing the songs ahead, waits its turn: while such work runs, for a
    // moment after it, and for the first seconds of a song. Safari answers
    // one store request after another, so a long check in the background
    // made the playing song wait
    let foregroundWork = 0;
    let foregroundAt = 0;

    const BACKGROUND_AFTER_MS = 1500;
    const BACKGROUND_SONG_START_MS = 4000;

    async function foreground(work) {

        foregroundWork += 1;

        try {
            return await work;
        } finally {

            foregroundWork -= 1;
            foregroundAt = Date.now();
        }
    }

    // Waits until nothing on the screen is waiting, then for a moment the
    // browser has nothing else to do
    async function backgroundTurn() {

        while (foregroundWork > 0 || Date.now() - foregroundAt < BACKGROUND_AFTER_MS
            || Date.now() - trackAskedAt < BACKGROUND_SONG_START_MS) {
            await sleep(250);
        }

        if (typeof window.requestIdleCallback === "function") {

            await new Promise(function (resolve) {
                window.requestIdleCallback(resolve, { timeout: 1000 });
            });
        }
    }

    // Whether the store holds the key, asked without reading what it holds.
    // In Safari match reads the whole stored file, some megabytes for a
    // song, and the startup check looking up every stored song that way
    // used so much memory that Safari closed the page
    async function storeHas(store, key, options) {

        const found = await store.keys(key, options);

        return !!(found && found.length > 0);
    }

    // An error in a few words for the debug log
    function errText(e) {
        return (e && e.name ? e.name + ": " : "") + (e && e.message ? e.message : String(e));
    }

    // Safari can stop answering for the stored songs while the page stays
    // open, most often after it was in the background a while: every read
    // fails with an internal error until the page is opened again. Songs
    // then play from Mureka, their waveforms are worked out from Mureka's
    // file, and a note says once that reloading the page brings the store
    // back. When the page is back in view it is asked again
    let storeBroken = false;

    function noteStoreBroken(e, doing) {

        dbgLog("Cache", "the browser's store failed while " + doing + ": " + errText(e));

        if (storeBroken) {
            return;
        }

        storeBroken = true;
        openStores.clear();
        probeIndexedDb();

        // A next song made ready from the store may no longer play either,
        // it is made ready again, from Mureka if need be
        dropNextReady();
        showToast("The browser stopped answering for the stored songs. They play from Mureka meanwhile,"
            + " reload the page to store songs again", false);
    }

    // Whether an error is the browser's store failing, Safari's internal
    // error, rather than the data or the network
    function isStoreFailure(e) {
        return !!(e && e.name === "TypeError" && /internal error/i.test(String(e.message)));
    }

    // Whether the browser's other store, IndexedDB, answers while the song
    // store does not, for the debug log
    function probeIndexedDb() {

        try {

            const t0 = Date.now();
            const req = indexedDB.open("mureka-probe");

            req.onsuccess = function () {

                dbgLog("Cache", "IndexedDB answers (" + (Date.now() - t0) + " ms)");
                req.result.close();
            };
            req.onerror = function () {
                dbgLog("Cache", "IndexedDB fails too: " + errText(req.error));
            };
        } catch (e) {
            dbgLog("Cache", "IndexedDB not reachable: " + errText(e));
        }
    }

    setInterval(checkStoreAgain, 30000);

    function checkStoreAgain() {

        if (!storeBroken || document.hidden) {
            return;
        }

        caches.open(AUDIO_CACHE).then(function (store) {
            return store.match("https://mureka-store-check/");
        }).then(function () {

            storeBroken = false;
            openStores.clear();
            dbgLog("Cache", "the browser's store answers again");
        }).catch(function () {
            // Still not answering, asked again next time
        });
    }

    // A song's file read from Mureka, for its waveform when the stored copy
    // cannot be read. Null when Mureka could not be reached
    async function songBytesFromMureka(song, url) {

        try {

            const got = await timedFetch(url, {}, 30000);

            if (!got || !got.ok) {
                return null;
            }

            const blob = await trackDownload(song, got).blob();

            cachingProgress.delete(song.song_id);

            return await blob.arrayBuffer();
        } catch (e) {

            dbgLog("Audio", "the file of " + song.song_id + " could not be read from Mureka: " + errText(e));
            return null;
        }
    }

    // How far a song being cached has come, in percent, 100 while its size
    // is not known
    function cachingPercent(id) {

        const c = cachingProgress.has(id) ? cachingProgress.get(id) : 0;

        return c < 0 ? 100 : Math.round(c * 100);
    }

    // The song id behind each pie in the song list, kept as the id itself,
    // a number or a string, the way the caching sets hold it
    const pieSongIds = new WeakMap();

    // One pie in the song list brought up to date
    function paintListPie(dot) {

        const pie = dot.firstElementChild;
        const key = pieSongIds.get(dot);

        if (!pie || key === undefined || !cachingIds.has(key)) {
            return;
        }

        const p = cachingPercent(key);

        pie.style.setProperty("--mureka-p", String(Math.max(4, p)));
        dot.title = "Caching, " + p + "%";
    }

    // The pie before the time: how much of the playing song is here. Stored
    // on this device, solid. Being stored, a pie filling as it comes in.
    // Neither, how much the player has loaded to play it. Nothing while
    // none of it is here
    function paintSongDot() {

        if (!songDotEl) {
            return;
        }

        const id = currentSong ? currentSong.song_id : null;
        let p = 0;
        let full = false;
        let loading = false;
        let ring = false;
        let tip = "";

        if (id !== null && cachedIds.has(id)) {

            full = true;
            tip = "The song is stored on this device";
        } else if (id !== null && cachingIds.has(id)) {

            loading = true;
            p = cachingPercent(id);
            tip = "Storing the song on this device, " + p + "%";
        } else if (id !== null && audio && audio.src) {

            const d = audio.duration;
            const b = audio.buffered;

            if (b && b.length > 0 && isFinite(d) && d > 0) {
                p = Math.min(100, Math.round(b.end(b.length - 1) * 100 / d));
            }

            full = p >= 99;
            loading = !full && p > 0;
            ring = full;
            tip = full ? "The whole song is loaded, not stored on this device" : "Loading the song, " + p + "%";
        }

        songDotEl.style.visibility = full || loading ? "visible" : "hidden";
        songDotEl.classList.toggle("mureka-pie-loading", loading);

        // Loaded in full but not stored, a ring rather than a solid dot, so
        // it is not taken for a stored song, which the list's dot shows
        songDotEl.classList.toggle("mureka-pie-ring", ring);
        songDotEl.style.setProperty("--mureka-p", String(loading ? Math.max(4, p) : 100));
        songDotEl.title = tip;
    }

    // Every pie brought up to date, once a second
    function paintCachePies() {

        paintSongDot();

        if (cachingIds.size === 0 || !listEl) {
            return;
        }

        for (const dot of listEl.querySelectorAll("[data-mureka-pie]")) {
            paintListPie(dot);
        }
    }

    // Current search box text, lowercased, empty means show all
    let searchQuery = "";

    // The list row of the currently playing song, used to scroll it into view
    let playingItemEl = null;

    // Which list view is active, one of mureka, queue or alpha
    let listView = settings.view;

    // The right-click options popup, built once and reused
    let contextMenuEl = null;

    // The song information overlay, built once and repopulated per song
    let infoEl = null;
    let infoBodyEl = null;
    let infoToken = 0;

    // The settings overlay and its controls, built once and reused
    let settingsEl = null;

    // The settings pages by name: the main list of pages, the two views,
    // this device, the connections, the music, backup and developer
    let settingsPages = null;

    // The settings page shown, main or one of the pages it opens
    let settingsPageNow = "main";

    // The page one level up: a profile's editor goes back to Sound, the
    // other pages to the main one
    function settingsParent(name) {
        return name === "soundedit" ? "sound" : "main";
    }

    function showSettingsPage(name) {

        if (!settingsPages) {
            return;
        }

        settingsPageNow = name;

        Object.keys(settingsPages).forEach(function (key) {
            settingsPages[key].style.display = key === name ? "flex" : "none";
        });

        if (settingsEl) {
            settingsEl.scrollTop = 0;
        }
    }
    let startDropRow = null;

    // The collapsible top action menu and its toggle in the header
    let actionsWrapEl = null;
    let actionsToggleBtn = null;

    // The floating view and filter dropdown and the bar that toggles it
    let viewMenuEl = null;
    let viewMenuBar = null;

    // The name of the view on that bar, the counts go beside it on a phone
    let viewMenuLabel = null;

    // The playlists overlay, its list container and the open button
    let playlistsEl = null;
    let playlistsListEl = null;
    let playlistButton = null;

    // Creator picker overlay parts and the action tile that opens it
    let creatorsEl = null;
    let creatorsListEl = null;
    let creatorsInputEl = null;
    let creatorButton = null;

    // Player UI element references
    let artWrapEl = null;
    let playerArt = null;
    let artPlaceholderEl = null;
    let playerTitle = null;
    let playerMetaEl = null;

    // The art and transport block. It lives at this scope because the keyboard
    // handling below runs outside the builder that creates it
    let playerEl = null;

    // Bring the art and transport block back after the keyboard has gone
    function showPlayerBlock() {

        if (!playerEl || playerEl.style.display !== "none") {
            return;
        }

        playerEl.style.display = "block";

        if (!swipeActive) {
            positionArt(0);
        }
    }

    // Take it away while the keyboard covers the lower half of the panel
    function hidePlayerBlock() {

        if (!playerEl || playerEl.style.display === "none") {
            return;
        }

        playerEl.style.display = "none";
    }

    // The walking text controller for the meta line. It is often longer than
    // the panel, and an ellipsis hides the tempo and the moods, which are the
    // useful part. The status line above the art uses one of its own
    let metaMarquee = null;
    let statusMarquee = null;

    // The last status text, kept so the line can be put back after its
    // marquee is built, which happens after the first status is set
    let statusText = "";

    // How long the text rests at the left before it starts, and again each time
    // it comes back around
    const META_SCROLL_DELAY = 3000;

    // Pixels per second, slow enough to read
    const META_SCROLL_SPEED = 40;

    // The clear space that follows the text before the next copy of it, at
    // least this, and at least half the line's width, so the next copy is
    // well apart and never seen coming in while the text rests
    const META_SCROLL_GAP = 72;
    const META_SCROLL_GAP_SHARE = 0.5;

    let playerCountsEl = null;

    // Synced lyric display, five stacked rows rolled on advance, rows are
    // {t: ms, text} for the current song only
    let lyricBox = null;
    let lyricSlots = [];

    // Overlay elements controlled by the art overlay mode
    let bottomScrimEl = null;
    let bottomWrapEl = null;

    // Toast shown when the overlay mode is cycled by a double tap
    let artToastEl = null;

    // Last tap on the art, for double tap detection on touch devices
    let lastArtTapT = 0;

    // Time of the last touch end on the art, to ignore the dblclick that iOS
    // synthesizes after a double tap
    let lastArtTouchEndT = 0;
    let lastArtTapX = 0;
    let lastArtTapY = 0;
    let lyricRows = [];
    let lyricIdx = -1;

    // Waveform seek bar, the normalized wave data for the current song
    let waveData = null;

    // The playing song's two waveforms, Mureka's and our own from the song.
    // waveData is the one this screen draws, the web view picks its own
    let waveMureka = null;
    let waveOwn = null;

    // The song whose waveform from Mureka is being looked for in the feed,
    // so the bar shows it is waiting
    let murekaWaveWait = null;

    // How loud each slice of our own waveform sounds, beside its peaks
    let waveOwnLoud = null;
    let waveCanvas = null;
    let seekBar = null;
    let curTimeEl = null;
    let remTimeEl = null;

    // The pie before the time, how much of the playing song is here
    let songDotEl = null;
    let playPauseBtn = null;
    let shuffleBtn = null;
    let repeatBtn = null;

    // True while the user is dragging the seek bar, so timeupdate does not fight it
    let isSeeking = false;

    // True when the last pause came from the user, either the panel button or
    // the MediaSession pause action. A pause without this flag is an operating
    // system interruption, such as a call or another app taking the audio
    let userPaused = false;

    // A song loaded without starting it: the song after one deleted while
    // the player was paused. Kept to that song and for a short while, so a
    // play pressed later is never swallowed
    let holdStart = null;

    // True while a track change is swapping the source. The media load
    // algorithm flips paused on a source change, and some engines fire a pause
    // event for it, which must not be mistaken for an interruption
    let switchingTrack = false;

    // The playToken that already got one retry after a load error, so a play
    // that fails twice stops instead of looping through retries
    let errorRetryToken = -1;

    // How many songs in a row failed to start. With no signal the queue should
    // skip past songs it cannot load rather than stopping, but not forever
    let playFailStreak = 0;

    // Album art coverflow and swipe state
    // artTiles is the row of cover images, the middle one is the current song
    let artTiles = [];

    // Counts every change to what the list holds, and the web view's sorted
    // copy of it made for that count. Declared early, the list renders
    // during startup
    let hostListStamp = 0;
    let hostListMemo = null;

    // Set as a swipe lands, so the song change it causes does not slide
    // the covers a second time
    let artSwipeLanded = false;

    // The song a slide from elsewhere is heading to, while it plays
    let artAutoId = "";
    let swipeActive = false;
    let swipeStartX = 0;
    let swipeStartY = 0;
    let swipeDir = 0;
    let currentSwipeOffset = 0;

    // Rising token so a new touch cancels any glide still animating
    let artGlideToken = 0;

    // The landing action of a glide still in flight, so it can be committed
    // rather than dropped if another gesture starts first
    let artGlidePending = null;

    // Pull to refresh state for the song list
    let pullArmed = false;
    let pulling = false;
    let pullStartY = 0;
    let pullDist = 0;
    let refreshing = false;

    // Small promise based delay helper
    function sleep(ms) {

        return new Promise(function (resolve) {
            setTimeout(resolve, ms);
        });
    }

    // Offline. The app opens the player on a page of its own when Mureka
    // cannot be reached, marked on the page, and tells the player whenever
    // the internet comes or goes. Offline only songs stored on this device
    // play and nothing is asked of Mureka, so nothing waits on a request
    // that cannot succeed
    let netOffline = false;

    // Whether the player runs on the app's offline page
    function offlinePage() {
        return document.documentElement.getAttribute("data-mureka-offline") === "1";
    }

    // Mureka found unreachable by the player itself, a song that would not
    // load and a check that got no answer, while the phone still claims to
    // be online. Asked again every 30 seconds until Mureka answers
    let netTrouble = false;
    let netTroubleTimer = 0;

    // The offline page counts only through these: opened there, the player
    // starts offline, and is online again as soon as the internet is back,
    // before the app has loaded Mureka's site again
    function offlineMode() {
        return netOffline || netTrouble;
    }

    // Whether a request goes to Mureka: its site, its api and its files
    function isMurekaRequest(resource) {

        const url = typeof resource === "string" ? resource : (resource && resource.url ? String(resource.url) : "");

        return url.charAt(0) === "/" || /^https?:\/\/([^/]*\.)?mureka\.ai(\/|$)/i.test(url);
    }

    // A request to Mureka refused at once while offline
    function offlineRefusal() {
        return Promise.reject(new Error("No internet, the player is offline"));
    }

    // fetch for Mureka, for what the user asked for: a like, a rename, a
    // publish. Always tried, offline too, since the offline mark may be
    // wrong, and an answer puts the player back online
    function murekaFetch(resource, options) {
        return watchMureka(resource, fetch(resource, options), options && options.signal);
    }

    // Until when the background requests go ahead offline too, because the
    // user asked for something that needs them, a load or a refresh
    let netTryUntil = 0;

    // The user asked for something that needs Mureka. Tried even offline:
    // its requests go ahead for a while, and the first answer puts the
    // player back online
    function userTry(what) {

        if (offlineMode()) {

            dbgLog("Offline", what + " asked for while offline, trying anyway");
            netTryUntil = Date.now() + 30000;
        }
    }

    // Every request to Mureka is watched: an answer of any kind shows Mureka
    // can be reached, no answer at all makes the player check at once
    // whether it is offline. A request its caller stopped says nothing
    function watchMureka(resource, request, callerSignal) {

        if (!isMurekaRequest(resource)) {
            return request;
        }

        return request.then(function (res) {

            murekaAnswered();
            return res;
        }, function (e) {

            // A request its caller stopped says nothing. In a browser one
            // that only ran out of time says the network is slow, not gone
            const timedOut = e && e.name === "AbortError";

            if (!(callerSignal && callerSignal.aborted) && !(timedOut && !isApkHost())) {
                murekaNoAnswer();
            }

            throw e;
        });
    }

    // fetch with a deadline. A request with no signal can hang until the
    // network stack finally gives up, which ties up the connection pool and
    // stalls the audio stream, so every background request uses this.
    // Offline, a request to Mureka is refused at once
    // A promise that settles by itself after ms, with null, when the one
    // given has not by then. For work whose answer may never come, so what
    // waits on it goes on
    function withinTime(promise, ms) {

        let timer = 0;

        const late = new Promise(function (resolve) {
            timer = setTimeout(function () {
                resolve(null);
            }, ms);
        });

        return Promise.race([Promise.resolve(promise).catch(function () {
            return null;
        }), late]).finally(function () {
            clearTimeout(timer);
        });
    }

    function timedFetch(resource, options, ms) {

        if (offlineMode() && isMurekaRequest(resource) && Date.now() > netTryUntil) {
            return offlineRefusal();
        }

        const opts = options || {};
        const limit = ms || 15000;

        if (typeof AbortController === "undefined") {
            return watchMureka(resource, fetch(resource, opts));
        }

        const controller = new AbortController();

        const timer = setTimeout(function () {
            controller.abort();
        }, limit);

        // A caller's own signal stops it too, a background download given
        // up for a song that was just tapped
        if (opts.signal) {

            if (opts.signal.aborted) {
                controller.abort();
            } else {
                opts.signal.addEventListener("abort", function () {
                    controller.abort();
                });
            }
        }

        const merged = Object.assign({}, opts, { signal: controller.signal });

        return watchMureka(resource, fetch(resource, merged).finally(function () {
            clearTimeout(timer);
        }), opts.signal);
    }

    // Read the cache from localStorage, return an empty cache on failure.
    // Given the stored text, as another tab wrote it, that is read instead,
    // and nothing waiting here is written over it first
    function loadCache(given) {

        let raw = null;

        if (typeof given !== "string") {
            flushPackedSave(true);
        }

        try {
            raw = typeof given === "string" ? given : localStorage.getItem(feed().cacheKey);

            if (raw) {

                const parsed = JSON.parse(unpackStored(raw));

                // Fill in fields that older cache versions may be missing
                if (!Array.isArray(parsed.songs)) {
                    parsed.songs = [];
                }

                // Re-trim so old caches shed dropped fields on their next save
                // Skip anything not a real song so one bad entry cannot throw here
                parsed.songs = parsed.songs.filter(function (s) {
                    return s && s.song_id !== undefined && s.song_id !== null;
                }).map(trim);

                if (typeof parsed.complete !== "boolean") {
                    parsed.complete = false;
                }

                if (parsed.lastCursor === undefined) {
                    parsed.lastCursor = null;
                }

                mergeLegacyPublished(parsed);

                return parsed;
            }
        } catch (e) {

            // A stored list that cannot be read is kept aside before an
            // empty one takes its place, so it is not lost with the next save
            if (raw) {
                keepBrokenLibrary(feed().cacheKey, raw);
            }
        }

        const empty = { songs: [], updated: 0, complete: false, lastCursor: null };

        mergeLegacyPublished(empty);

        return empty;
    }

    // Published used to be a separate feed with its own cache, which may hold
    // songs this one has not paged back to yet. Fold those in once so nothing
    // disappears on upgrade, then drop the old key. Only the account's own library has a
    // legacy cache, a creator feed never did
    function mergeLegacyPublished(target) {

        if (creatorSource) {
            return;
        }

        try {

            const raw = localStorage.getItem(LEGACY_PUBLISHED_KEY);

            if (!raw) {
                return;
            }

            const old = JSON.parse(raw);
            const songs = Array.isArray(old && old.songs) ? old.songs : [];

            const known = new Set(target.songs.map(function (s) {
                return s.song_id;
            }));

            let added = 0;

            for (const s of songs) {

                if (!isUsableSong(s) || known.has(s.song_id)) {
                    continue;
                }

                known.add(s.song_id);
                target.songs.push(trim(s));
                added += 1;
            }

            // Merged songs came from the published feed, so the combined list is
            // no longer a complete page run and should be scanned again
            if (added > 0) {

                target.complete = false;
                target.lastCursor = null;
            }

            localStorage.removeItem(LEGACY_PUBLISHED_KEY);
        } catch (e) {
        }
    }

    // Remove every other creator cache, freeing space for the active one
    // The own feed caches and the active key are kept
    function pruneCreatorCaches(keepKey) {

        try {
            const remove = [];

            for (let i = 0; i < localStorage.length; i += 1) {

                const k = localStorage.key(i);

                if (k && k.indexOf("mureka_autoload_creator_") === 0 && k !== keepKey) {
                    remove.push(k);
                }
            }

            remove.forEach(function (k) {
                localStorage.removeItem(k);
            });
        } catch (e) {
        }
    }

    function packStored(text) {

        if (text.length < PACK_FROM) {
            return text;
        }

        const bytes = new TextEncoder().encode(text);
        const codes = new Uint16Array(bytes.length + 2);
        let n = 0;
        let dict = new Map();
        let next = 257;
        let w = -1;

        for (let i = 0; i < bytes.length; i++) {

            const c = bytes[i];

            if (w < 0) {

                w = c;
                continue;
            }

            const hit = dict.get(w * 256 + c);

            if (hit !== undefined) {

                w = hit;
                continue;
            }

            codes[n++] = w;

            if (next < LZW_MAX) {

                dict.set(w * 256 + c, next);
                next += 1;
            } else {

                codes[n++] = LZW_RESET;
                dict = new Map();
                next = 257;
            }

            w = c;
        }

        if (w >= 0) {
            codes[n++] = w;
        }

        const parts = [PACK_MARK];

        for (let i = 0; i < n; i += 8192) {

            const slice = codes.subarray(i, Math.min(n, i + 8192));
            const shifted = new Array(slice.length);

            for (let k = 0; k < slice.length; k++) {
                shifted[k] = slice[k] + LZW_BASE;
            }

            parts.push(String.fromCharCode.apply(null, shifted));
        }

        return parts.join("");
    }

    // The text back from what packStored made. Plain text, as stored by
    // earlier versions and for small lists, comes back as it is
    function unpackStored(raw) {

        if (typeof raw !== "string" || raw.indexOf(PACK_MARK) !== 0) {
            return raw;
        }

        const prefix = new Int32Array(LZW_MAX);
        const suffix = new Uint8Array(LZW_MAX);
        const first = new Uint8Array(LZW_MAX);
        const len = new Int32Array(LZW_MAX);
        let out = new Uint8Array(Math.max(1024, raw.length * 4));
        let pos = 0;
        let next = 257;
        let prev = -1;

        for (let c = 0; c < 256; c++) {

            prefix[c] = -1;
            suffix[c] = c;
            first[c] = c;
            len[c] = 1;
        }

        // Room for this many more bytes
        const room = function (more) {

            if (pos + more <= out.length) {
                return;
            }

            const bigger = new Uint8Array(Math.max(out.length * 2, pos + more));

            bigger.set(out.subarray(0, pos));
            out = bigger;
        };

        // A table entry's bytes, written from its end back along its prefixes
        const write = function (code) {

            const l = len[code];
            let k = code;

            room(l);

            for (let i = pos + l - 1; i >= pos; i--) {

                out[i] = suffix[k];
                k = prefix[k];
            }

            pos += l;
        };

        for (let i = PACK_MARK.length; i < raw.length; i++) {

            const code = raw.charCodeAt(i) - LZW_BASE;
            let head;

            if (code === LZW_RESET) {

                next = 257;
                prev = -1;
                continue;
            }

            if (code >= 0 && code < next) {

                write(code);
                head = first[code];
            } else if (code === next && prev >= 0) {

                write(prev);
                room(1);
                out[pos++] = first[prev];
                head = first[prev];
            } else {
                throw new Error("The stored song list is damaged");
            }

            if (prev >= 0 && next < LZW_MAX) {

                prefix[next] = prev;
                suffix[next] = head;
                first[next] = first[prev];
                len[next] = len[prev] + 1;
                next += 1;
            }

            prev = code;
        }

        return new TextDecoder().decode(out.subarray(0, pos));
    }

    // Write the song list waiting, made into text once. A large one is
    // packed by the worker when there is one, else here. Asked to be done
    // at once, as when the page is hidden or closed or a list is read back,
    // it is packed here, and a list the worker still has is written too, as
    // the page may be gone before the worker answers
    function flushPackedSave(now) {

        clearTimeout(packedSaveTimer);
        packedSaveTimer = 0;

        if (now === true) {
            writeWaitingPacks();
        }

        if (!packedSave) {
            return;
        }

        const job = packedSave;
        const text = JSON.stringify(job.list);
        const seq = ++packSeq;

        packedSave = null;

        if (text.length < PACK_FROM) {

            writeLibraryAt(job.key, seq, text);
            return;
        }

        const worker = now === true ? null : packingWorker();

        if (!worker) {

            writeLibraryAt(job.key, seq, packStored(text));
            return;
        }

        packWaiting.set(job.key, { seq: seq, text: text });

        try {
            worker.postMessage({ seq: seq, key: job.key, text: text });
        } catch (e) {
            packWorkerFailed();
        }
    }

    // A list written unless a newer one of the same key was written already
    function writeLibraryAt(key, seq, payload) {

        if ((packWritten.get(key) || 0) > seq) {
            return;
        }

        packWritten.set(key, seq);
        writeLibrary(key, payload);
    }

    // The lists the worker has not answered for, packed and written here
    function writeWaitingPacks() {

        for (const [key, job] of Array.from(packWaiting.entries())) {

            packWaiting.delete(key);
            writeLibraryAt(key, job.seq, packStored(job.text));
        }
    }

    // The worker, made from packStored itself and the constants it uses.
    // A page whose rules refuse a worker made this way gets none, and the
    // lists are packed on the page as before
    function packingWorker() {

        if (packWorker !== undefined) {
            return packWorker;
        }

        packWorker = null;

        if (typeof Worker !== "function" || typeof Blob !== "function") {
            return null;
        }

        try {

            const src = "\"use strict\";\n"
                + "const PACK_FROM = " + PACK_FROM + ";\n"
                + "const PACK_MARK = " + JSON.stringify(PACK_MARK) + ";\n"
                + "const LZW_MAX = " + LZW_MAX + ";\n"
                + "const LZW_RESET = " + LZW_RESET + ";\n"
                + "const LZW_BASE = " + LZW_BASE + ";\n"
                + packStored.toString() + "\n"
                + "self.onmessage = function (ev) {\n"
                + "    self.postMessage({ seq: ev.data.seq, key: ev.data.key, packed: packStored(ev.data.text) });\n"
                + "};\n";
            const url = URL.createObjectURL(new Blob([src], { type: "text/javascript" }));
            const worker = new Worker(url);

            URL.revokeObjectURL(url);
            worker.onmessage = function (ev) {

                const d = ev.data || {};
                const job = packWaiting.get(d.key);

                // Only the answer for the newest list of that key
                if (!job || job.seq !== d.seq || typeof d.packed !== "string") {
                    return;
                }

                packWaiting.delete(d.key);
                writeLibraryAt(d.key, d.seq, d.packed);
            };
            worker.onerror = function () {
                packWorkerFailed();
            };
            packWorker = worker;
            dbgLog("Storage", "large song lists are packed in a worker");
        } catch (e) {

            packWorker = null;
            dbgLog("Storage", "no worker for packing here, packed on the page");
        }

        return packWorker;
    }

    // The worker could not be made or stopped: none from now on, and what
    // it had is packed here
    function packWorkerFailed() {

        if (packWorker) {

            try {
                packWorker.terminate();
            } catch (e) {
                // Gone already
            }
        }

        packWorker = null;
        dbgLog("Storage", "the packing worker failed, packed on the page");
        writeWaitingPacks();
    }

    window.addEventListener("pagehide", function () {
        flushPackedSave(true);
    });
    document.addEventListener("visibilitychange", function () {

        if (document.visibilityState === "hidden") {
            flushPackedSave(true);
        }
    });

    // Persist the cache to localStorage, a moment later, once for a burst
    // of changes. The wait is not pushed back by every change, so a list
    // changing all the time is still written every SAVE_DELAY_MS. A change
    // to another feed's list first writes the one waiting
    function saveCache() {

        exportsVersion += 1;

        const key = feed().cacheKey;

        if (packedSave && packedSave.key !== key) {
            flushPackedSave(false);
        }

        packedSave = { key: key, list: cache };

        if (!packedSaveTimer) {

            packedSaveTimer = setTimeout(function () {
                flushPackedSave(false);
            }, SAVE_DELAY_MS);
        }
    }

    // Store a song list, as it is or packed. If storage is full, drop other
    // creator caches and retry once so the active library always saves and
    // survives a restart
    function writeLibrary(key, payload) {

        try {
            localStorage.setItem(key, payload);
            storageSaved();
            return true;
        } catch (e) {
        }

        pruneCreatorCaches(key);

        try {
            localStorage.setItem(key, payload);
            storageSaved();
            return true;
        } catch (e) {
            storageFailed();
            return false;
        }
    }

    // Saving the song list failed: the browser's storage is full or turned
    // off. Said at once and again every few minutes while it lasts, since
    // changes made meanwhile are gone with the next start
    function storageFailed() {

        const now = Date.now();

        storageProblemAt = storageProblemAt || now;
        dbgLog("Storage", "the song list could not be saved");

        if (now - storageWarnedAt < STORAGE_WARN_MS) {
            return;
        }

        storageWarnedAt = now;
        setStatus("The song list could not be saved, the browser's storage is full or turned off");
        showToast("Could not save the song list, storage is full", false);
    }

    function storageSaved() {

        if (!storageProblemAt) {
            return;
        }

        storageProblemAt = 0;
        storageWarnedAt = 0;
        dbgLog("Storage", "the song list is saved again");
        showToast("The song list is saved again");
    }

    // A stored song list that could not be read, kept under a key of its
    // own for a look later, and said once the player is up
    function keepBrokenLibrary(key, raw) {

        let kept = false;

        try {
            localStorage.setItem(key + "_broken", raw);
            kept = true;
        } catch (e) {
            // No room for a copy either
        }

        brokenLibraryNote = kept
            ? "The stored song list could not be read. A copy was kept, Load brings the songs back from Mureka"
            : "The stored song list could not be read. Load brings the songs back from Mureka";
        dbgLog("Storage", "the stored song list under " + key + " could not be read" + (kept ? ", a copy was kept" : ""));
    }

    // Another tab on this site saved the song list. It is taken over here,
    // the same songs kept as the same copies, so the next save here does
    // not throw away what the other tab did
    function followOtherTabs() {

        window.addEventListener("storage", function (ev) {

            if (ev.storageArea !== localStorage || ev.key !== feed().cacheKey || !ev.newValue) {
                return;
            }

            const other = loadCache(ev.newValue);

            cache.songs = keepSongCopies(other.songs, cache.songs);
            cache.updated = other.updated;
            cache.complete = other.complete;
            cache.lastCursor = other.lastCursor;
            dbgLog("Storage", "the song list was changed in another tab, " + cache.songs.length + " songs");
            renderList();
            publishHostSoon();
        });
    }

    // The pace of the fresh play counts, the shortest wait of a range: 5 to
    // 10, 10 to 30 or 30 to 60 seconds. A fixed 60 from before is the slowest
    function playsPaceFrom(v) {

        if (v === 5 || v === 10 || v === 30) {
            return v;
        }

        return v === 60 ? 30 : 10;
    }

    // A wait somewhere in the chosen range, in milliseconds, so the requests
    // come at uneven times like a person's
    function playsPaceMs() {

        const low = playsPaceFrom(settings.playsTrickleSecs);
        const high = low === 5 ? 10 : (low === 10 ? 30 : 60);

        return Math.round((low + Math.random() * (high - low)) * 1000);
    }

    // A whole number from saved settings, kept inside its range, or the
    // default when it is missing or not a number
    function numberIn(v, min, max, fallback) {

        const n = parseInt(v, 10);

        if (!isFinite(n)) {
            return fallback;
        }

        return Math.max(min, Math.min(max, n));
    }

    // The pace once every count is up to date, the shortest wait of a range
    // in minutes: 1 to 3, 3 to 10 or 10 to 30, or 0 when it waits for counts
    // to grow old instead
    function playsKeepMs() {

        const low = settings.playsKeepMins;

        if (low !== 1 && low !== 3 && low !== 10) {
            return 0;
        }

        const high = low === 1 ? 3 : (low === 3 ? 10 : 30);

        return Math.round((low + Math.random() * (high - low)) * 60000);
    }

    // How long the counts and lyrics of a song are kept, in minutes. Older
    // settings kept it in hours, 4 unless changed: a changed value carries
    // over, the old default becomes the new one of 30 minutes
    function countsMinutesFrom(parsed) {

        const m = parsed.countsMaxMinutes;

        if (typeof m === "number" && m >= 5 && m <= 1440) {
            return m;
        }

        const h = parsed.countsMaxAge;

        if (typeof h === "number" && h >= 1 && h <= 72 && h !== 4) {
            return Math.min(1440, h * 60);
        }

        return 30;
    }

    // A number kept within its range, or the fallback
    function numberIn(v, lo, hi, fallback) {
        return typeof v === "number" && v >= lo && v <= hi ? v : fallback;
    }

    // The web view's own screen off. Before it had one it followed the
    // mobile player's, so a settings file without it starts from those
    function webScreenFrom(parsed) {

        const pick = function (webKey, phoneKey, lo, hi, fallback) {
            return numberIn(parsed[webKey], lo, hi, numberIn(parsed[phoneKey], lo, hi, fallback));
        };

        const text = function (webKey, phoneKey, fallback) {

            if (typeof parsed[webKey] === "string") {
                return parsed[webKey];
            }

            return typeof parsed[phoneKey] === "string" ? parsed[phoneKey] : fallback;
        };

        return {
            on: typeof parsed.webBlackout === "boolean" ? parsed.webBlackout : parsed.carBlackout === true,
            after: pick("webAutoBlack", "carAutoBlack", 0, 300, 20),
            text: text("webMarkText", "blackoutText", "\u266B"),
            color: text("webMarkColor", "blackoutColor", "#333333"),
            size: pick("webMarkSize", "blackoutSize", 12, 240, 64),
            drift: pick("webMarkDrift", "blackoutDrift", 5, 120, 25)
        };
    }

    // The web view's bar from stored settings. Before Songs could be placed
    // it always stood at the end of the bar, so a bar stored then gets it
    // there once
    function webControlsFrom(parsed) {

        const stored = typeof parsed.webControlOrder === "string" && parsed.webControlOrder
            ? parsed.webControlOrder : "repeat,shuffle,stop,play";

        if (parsed.webControlsV2 === true || stored.split(",").indexOf("songs") >= 0) {
            return stored;
        }

        return stored + ",songs";
    }

    // The kinds left out of an import: as chosen last time for the kinds
    // there were then, and as by default for kinds added since. Settings
    // from before the list was remembered knew the first five kinds
    function loadImportSkip(parsed) {

        if (!Array.isArray(parsed.importSkip)) {
            return IMPORT_SKIP_DEFAULT.slice();
        }

        const seen = Array.isArray(parsed.importSeen)
            ? parsed.importSeen
            : ["rating", "bpm", "instr", "trimmed", "creators"];

        return IMPORT_TYPE_KEYS.filter(function (k) {

            return seen.indexOf(k) >= 0
                ? parsed.importSkip.indexOf(k) >= 0
                : IMPORT_SKIP_DEFAULT.indexOf(k) >= 0;
        });
    }

    // Read the settings from localStorage, falling back to safe defaults
    // As last time is the default start, refresh on open is off for both feeds
    // Autoplay is off, the default play mode is not shuffled, repeat is all
    function returnMinutes(v) {

        const n = parseInt(v, 10);

        if (!isFinite(n) || n < 1) {
            return REFRESH_RETURN_DEFAULT;
        }

        const stepped = Math.round(n / REFRESH_RETURN_STEP) * REFRESH_RETURN_STEP;

        return Math.max(REFRESH_RETURN_STEP, Math.min(stepped, REFRESH_RETURN_MAX));
    }

    // Play on after a quick restart, in seconds: 0 turns it off, otherwise
    // in steps of 5 up to ten minutes. Missing, it is half a minute. The
    // limits are declared near the top, the settings are read before this
    // The seconds a song fades out before another, 0 to 10 to a hundredth,
    // the default given when not set
    function fadeSeconds(v, fallback) {

        const n = Number(v);

        return Number.isFinite(n) && n >= 0 ? Math.min(10, Math.round(n * 100) / 100) : fallback;
    }

    // The silence before a paused song fades in as it plays on, 0 to 5 to a
    // tenth, half a second when not set
    function hushSeconds(v) {

        const n = Number(v);

        return Number.isFinite(n) && n >= 0 ? Math.min(5, Math.round(n * 10) / 10) : 0.5;
    }

    // An order of the web view's badges kept or sent, as known badge names,
    // each once. The names in the order they come without one set: online,
    // heat, battery, WireGuard and hotspot. Kept in here, as the settings
    // are read before the constants further down are set
    function badgeOrderFrom(v) {

        const known = ["net", "heat", "battery", "wg", "hotspot"];
        const list = Array.isArray(v) ? v : String(v || "").split(",");
        const seen = {};

        return list.map(function (name) {
            return String(name).trim().toLowerCase();
        }).filter(function (name) {

            if (known.indexOf(name) === -1 || seen[name]) {
                return false;
            }

            seen[name] = true;

            return true;
        });
    }

    function readyFadeSeconds(v) {
        return fadeSeconds(v, 1.5);
    }

    // The lyrics length under which a song counts as instrumental, 0 for
