        play: { label: "Play", icon: "play", el: "play" },
        stop: { label: "Stop", icon: "stop", el: "stopBtn" },
        next: { label: "Next", icon: "next", el: "next" },
        shuffle: { label: "Shuffle", icon: "shuffle", el: "shuffle" },
